return ['project-id-version'=>'iFly Nepal','report-msgid-bugs-to'=>'','pot-creation-date'=>'2026-09-24 07:55+0000','po-revision-date'=>'2026-09-24 11:50+0000','last-translator'=>'iFly Nepal','language-team'=>'French (France)','language'=>'fr_FR','plural-forms'=>'nplurals=2; plural=n > 1;','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','x-generator'=>'Loco https://localise.biz/','x-loco-version'=>'2.8.8; wp-7.1.2; php-8.2.29','x-domain'=>'iflynepal','messages'=>['%1$d departure in %2$s'=>'%1$d départ en %2$s' . "\0" . '%1$d départs en %2$s','%1$s and %2$s'=>'%1$s et %2$s','%1$s on %2$s'=>'%1$s sur %2$s','%1$s, %2$s'=>'%1$s, %2$s','%1$s, %2$s for %3$s'=>'%1$s, %2$s pour %3$s','%1$s, global representative in %2$s'=>'%1$s, représentant·e mondial·e au %2$s','%1$s, representative in %2$s'=>'%1$s, représentant·e au %2$s','%s article matches.'=>'%s article correspond.' . "\0" . '%s articles correspondent.','%s blog matches.'=>'%s blog correspond.' . "\0" . '%s blogs correspondent.','%s min read'=>'%s min de lecture','%s story matches.'=>'%s actualité correspond.' . "\0" . '%s actualités correspondent.','&ldquo;%s&rdquo;'=>'&laquo;&nbsp;%s&nbsp;&raquo;','(depending on season)'=>'(selon la saison)','1. Fee required to obtain Tourist Visa from Nepalese diplomatic agencies and entry points:'=>'1. Frais requis pour obtenir un visa touristique auprès des missions diplomatiques népalaises et des points d\'entrée :','15&ndash;29 days prior to departure'=>'15 à 29 jours avant le départ','2. Fee to be levied for renewal or regularization of tourist visa'=>'2. Frais à percevoir pour le renouvellement ou la régularisation du visa touristique','24/7 Personalized Support'=>'Assistance personnalisée 24h/24 et 7j/7','30+ days prior to departure'=>'30 jours ou plus avant le départ','50% refund'=>'Remboursement de 50 %','9:00 AM to 5:00 PM'=>'9h00 à 17h00','<em>Retreats</em> in Nepal'=>'<em>Retraites</em> au Népal','<strong>Advertising cookies</strong> — we may partner with advertising networks, such as Facebook or Google Ads, to display relevant ads based on your browsing behaviour.'=>'<strong>Cookies publicitaires</strong> — nous pouvons collaborer avec des réseaux publicitaires, tels que Facebook ou Google Ads, afin d\'afficher des publicités pertinentes selon votre comportement de navigation.','<strong>Analyse website performance</strong>.'=>'<strong>Analyser les performances du site</strong>.','<strong>Analytical cookies</strong> — we use tools like Google Analytics to understand how visitors interact with our website. These cookies are anonymous and help us improve site performance.'=>'<strong>Cookies analytiques</strong> — nous utilisons des outils comme Google Analytics pour comprendre comment les visiteurs interagissent avec notre site. Ces cookies sont anonymes et nous aident à améliorer les performances du site.','<strong>Essential cookies</strong> — necessary for basic site functionality, such as security, navigation and booking.'=>'<strong>Cookies essentiels</strong> — nécessaires au fonctionnement de base du site, tels que la sécurité, la navigation et la réservation.','<strong>Functional cookies</strong> — these remember your preferences, such as language or region, to enhance your experience.'=>'<strong>Cookies fonctionnels</strong> — ils mémorisent vos préférences, telles que la langue ou la région, afin d\'améliorer votre expérience.','<strong>IP address, device type</strong>, and browser information.'=>'<strong>Adresse IP, type d\'appareil</strong>, et informations sur le navigateur.','<strong>Legal authorities</strong>, only if required by law.'=>'<strong>Autorités légales</strong>, uniquement si la loi l\'exige.','<strong>Location data</strong> (if enabled).'=>'<strong>Données de localisation</strong> (si activées).','<strong>Lukla, Jomsom, Pokhara</strong> and other mountain flights are prone to weather-related delays or cancellations.'=>'Les vols vers <strong>Lukla, Jomsom, Pokhara</strong> et d\'autres destinations montagneuses sont sujets à des retards ou annulations liés à la météo.','<strong>Name, email address, phone number</strong>, and mailing address.'=>'<strong>Nom, adresse e-mail, numéro de téléphone</strong>, et adresse postale.','<strong>Offset carbon emissions</strong> from flights and transport through verified projects.'=>'<strong>Compenser les émissions de carbone</strong> des vols et des transports via des projets certifiés.','<strong>Passport details</strong> for booking and permit processing.'=>'<strong>Informations de passeport</strong> pour la réservation et le traitement des permis.','<strong>Payment processors</strong> and booking systems.'=>'<strong>Prestataires de paiement</strong> et systèmes de réservation.','<strong>Prohibit bribery, fraud, and corruption</strong> at all levels.'=>'<strong>Interdire la corruption, la fraude et les pots-de-vin</strong> à tous les niveaux.','<strong>Trusted third-party service providers</strong> (e.g. hotel partners, trekking guides, transportation companies).'=>'<strong>Prestataires de services tiers de confiance</strong> (par exemple, hôtels partenaires, guides de randonnée, sociétés de transport).','A <strong>deposit (typically 20&ndash;30%)</strong> is required to confirm your booking. The remaining balance is payable prior to the start of your trip or on arrival, depending on the itinerary.'=>'Un <strong>acompte (généralement de 20 à 30 %)</strong> est requis pour confirmer votre réservation. Le solde restant est payable avant le début de votre voyage ou à l\'arrivée, selon l\'itinéraire.','A booking is only confirmed once we issue a <strong>confirmation email</strong>.'=>'Une réservation n\'est confirmée qu\'après l\'envoi d\'un <strong>e-mail de confirmation</strong>.','A community gathering outdoors in rural Nepal'=>'Un rassemblement communautaire en plein air dans le Népal rural','A copy of your data'=>'Une copie de vos données','A cultural gathering in Kathmandu, Nepal'=>'Un rassemblement culturel à Katmandou, au Népal','A dedicated <strong>Sustainability Coordinator</strong> oversees implementation, reporting, and continuous improvement of our policies.'=>'Un·e <strong>coordinateur/coordinatrice de durabilité</strong> dédié·e supervise la mise en œuvre, le suivi et l\'amélioration continue de nos politiques.','A few examples of your local currency.'=>'Quelques exemples de votre monnaie locale.','A full supply of any medication you require for the duration of your stay, along with the prescription.'=>'Une réserve complète de tout médicament nécessaire pour la durée de votre séjour, accompagnée de l\'ordonnance.','A head torch is especially useful during power cuts.'=>'Une lampe frontale est particulièrement utile en cas de coupure de courant.','A high Himalayan view in Nepal'=>'Une vue sur les hauts sommets de l\'Himalaya au Népal','A hiker admiring the Everest region in Nepal'=>'Un randonneur admirant la région de l\'Everest au Népal','A Kathmandu-based expert is a message away, day or night, before and during your trip.'=>'Un expert basé à Katmandou est à un message de vous, jour et nuit, avant et pendant votre voyage.','A new Prime Minister was sworn in, supported by all parties except the Maoists.'=>'Un nouveau Premier ministre a été assermenté, soutenu par tous les partis sauf les maoïstes.','A tourist who has departed before the expiry of the period specified in the visa issued in a visa year shall not be allowed to use the visa by adding the remaining period to another visa year.'=>'Un touriste ayant quitté le pays avant l\'expiration de la période indiquée sur le visa délivré pour une année de visa donnée ne sera pas autorisé à reporter la période restante sur une autre année de visa.','A traveller looking out over the Himalaya in Nepal'=>'Un voyageur contemplant l\'Himalaya au Népal','A traveller sitting alone at the end of a jetty, looking out across a still mountain lake'=>'Un voyageur assis seul au bout d\'un ponton, contemplant un lac de montagne immobile','A week can cover a focused city-and-nature trip. Ten to fourteen days gives more room for a major trek, multi-destination tour or a travel-and-retreat combination.'=>'Une semaine permet de couvrir un voyage ciblé entre ville et nature. Dix à quatorze jours laissent plus de place pour un grand trek, un circuit multi-destinations ou une combinaison voyage et retraite.','A woman carrying milk cans along a rural road in Ilam, Nepal'=>'Une femme portant des bidons de lait le long d\'une route rurale à Ilam, au Népal','a. Entry:'=>'a. Entrée :','About'=>'À propos','About %s'=>'À propos de %s','About Nepal'=>'À propos du Népal','About this article'=>'À propos de cet article','About this blog'=>'À propos de ce blog','About this news'=>'À propos de cette actualité','Above the tree line, rhododendron, juniper scrub and other procumbent woody vegetation may extend to about 4200m where it is then succeeded by t a tundra-like association of short grasses, sedge mosses and alpine plants wherever there is sufficient soil. This continues up to the lower limit of perpetual snow and ice at about 5100m. The mammalian faun is sparse and unlikely to include any species other than Himalayan marmots, mouse hare, tahr, musk deer, snow leopard and occasionally blue sheep. In former times, the wild Yak and great Tibetan sheep could also be sighted in this region and it is possible that a few may still be surviving in areas such as Dolpa and Humla. The bird life at such as lammergeyer, snowcock, snowpatridge, choughs and bunting, with redstarts and dippers often seen along the streams and rivulets. Yaks are the only livestock, which thrive at high altitude. They serve both back and draught animals. The cheeses prepared out of the milk are edible for months. The female Yak provides milk to the Sherpas. Of the wonderful flora and fauna must suffice to indicate what a paradise Nepal is to the lovers of wild animal and bird life, to the naturalists and to the foresters.'=>'Au-dessus de la limite forestière, les rhododendrons, les buissons de genévriers et d’autres végétaux ligneux rampants peuvent s’étendre jusqu’à environ 4 200 m d’altitude, où ils cèdent alors la place à une végétation de type toundra, composée de graminées courtes, de carex, de mousses et de plantes alpines, partout où le sol est suffisamment épais. Cette végétation se prolonge jusqu’à la limite inférieure des neiges et glaces perpétuelles, à environ 5 100 m. La faune mammifère est clairsemée et ne comprend probablement aucune espèce autre que les marmottes de l’Himalaya, le lièvre-souris, le tahr, le cerf musqué, le léopard des neiges et, occasionnellement, le moussaillon. Autrefois, on pouvait également apercevoir dans cette région des yaks sauvages et de grands moutons tibétains ; il est possible que quelques-uns survivent encore dans des zones telles que Dolpa et Humla. La faune aviaire comprend notamment le gypaète barbu, le coq des neiges, la perdrix des neiges, le crave à bec rouge et le bruant, tandis que l’on aperçoit souvent des rouges-queues et des cincles plongeurs le long des ruisseaux et des cours d’eau. Les yaks sont les seuls animaux d’élevage qui prospèrent en haute altitude. Ils servent à la fois d’animaux de bât et de trait. Les fromages préparés à partir de leur lait se conservent pendant des mois. La femelle yak fournit du lait aux sherpas. Il suffit de mentionner cette merveilleuse faune et cette flore pour montrer à quel point le Népal est un paradis pour les amoureux de la faune sauvage et de l’avifaune, pour les naturalistes et pour les sylviculteurs.','Accommodation & Itinerary Changes'=>'Hébergement et modifications d\'itinéraire','Account information, if you create an account'=>'Informations de compte, si vous créez un compte','Accountability and integrity in how we run and report on the business.'=>'Responsabilité et intégrité dans la gestion et le reporting de notre activité.','Across every part of our operations, from the trail to the office.'=>'Dans tous les aspects de nos activités, du sentier au bureau.','Across the world'=>'À travers le monde','Administrative, legal or tax purposes'=>'Fins administratives, légales ou fiscales','Adopt energy-efficient, water-saving, and waste-reducing office practices.'=>'Adopter des pratiques de bureau économes en énergie, en eau et réduisant les déchets.','Advertising Cookies'=>'Cookies publicitaires','After many years of struggle when the political parties were banned, they finally mustered enough courage to start a People&rsquo;s Movement in 1990. Paving way for democracy, the then-King Birendra accepted constitutional reforms and established a multiparty parliament with King as the Head of State and an executive Prime Minister. In May 1991, Nepal held its first parliamentary elections. In February 1996, the Maoist parties declared People&rsquo;s War against monarchy and the elected government. Then on 1st June 2001, a horrific tragedy wiped out the entire royal family including King Birendra and Queen Aishwarya with many of their closest relatives. With only King Birendra&rsquo;s brother, Gyanendra and his family surviving, he was crowned the king. King Gyanendra abided by the elected government for some time and then dismissed the elected Parliament to wield absolute power. In April 2006, another People&rsquo;s Movement was launched jointly by the democratic parties focusing most energy in Kathmandu which led to a 19-day curfew. Eventually, King Gyanendra relinquished his power and reinstated the Parliament. On November 21, 2006, Prime Minister Girija Prasad Koirala and Maoist chairman Prachanda signed the Comprehensive Peace Agreement (CPA) 2006, committing to democracy and peace for the progress of the country and people. A Constituent Assembly election was held on April 10, 2008. On May 28, 2008, the newly elected Constituent Assembly declared Nepal a Federal Democratic Republic, abolishing the 240 year-old monarchy. Nepal today has a President as Head of State and a Prime Minister heading the Government.'=>'Après de nombreuses années de lutte, alors que les partis politiques étaient interdits, ils ont finalement trouvé le courage nécessaire pour lancer un « Mouvement populaire » en 1990. Ouvrant la voie à la démocratie, le roi Birendra, alors au pouvoir, a accepté des réformes constitutionnelles et mis en place un parlement multipartite, avec le roi comme chef de l’État et un Premier ministre à la tête du pouvoir exécutif. En mai 1991, le Népal a organisé ses premières élections législatives. En février 1996, les partis maoïstes ont déclaré une « guerre populaire » contre la monarchie et le gouvernement élu. Puis, le 1er juin 2001, une terrible tragédie a anéanti toute la famille royale, y compris le roi Birendra et la reine Aishwarya, ainsi que bon nombre de leurs proches. Seuls le frère du roi Birendra, Gyanendra, et sa famille ayant survécu, ce dernier fut couronné roi. Le roi Gyanendra s’est conformé aux décisions du gouvernement élu pendant un certain temps, puis a dissous le Parlement élu afin d’exercer un pouvoir absolu. En avril 2006, un nouveau « Mouvement populaire » a été lancé conjointement par les partis démocratiques, qui ont concentré l’essentiel de leurs efforts à Katmandou, ce qui a conduit à un couvre-feu de 19 jours. Finalement, le roi Gyanendra a renoncé à son pouvoir et rétabli le Parlement. Le 21 novembre 2006, le Premier ministre Girija Prasad Koirala et le président maoïste Prachanda ont signé l’Accord de paix global (CPA) de 2006, s’engageant en faveur de la démocratie et de la paix pour le progrès du pays et de la population. Des élections à l’Assemblée constituante ont eu lieu le 10 avril 2008. Le 28 mai 2008, l’Assemblée constituante nouvellement élue a proclamé le Népal République démocratique fédérale, abolissant ainsi la monarchie vieille de 240 ans. Aujourd’hui, le Népal a un président comme chef de l’État et un Premier ministre à la tête du gouvernement.','Agriculture'=>'Agriculture','Air Quality Protection:'=>'Protection de la qualité de l\'air :','All'=>'Tous','All news'=>'Toutes les actualités','All rights reserved.'=>'Tous droits réservés.','Alpine terrain above the tree line in the Nepal Himalaya'=>'Terrain alpin au-dessus de la limite forestière dans l\'Himalaya népalais','Alternative arrangements (helicopter charter, rescheduling, overland options) may be offered <strong>at additional cost</strong>.'=>'Des solutions alternatives (affrètement d\'hélicoptère, report, options terrestres) peuvent être proposées <strong>moyennant un coût supplémentaire</strong>.','Altitude sickness is a risk, including on the Annapurna, Langtang and Everest Base Camp treks.'=>'Le mal des montagnes est un risque, y compris sur les treks de l\'Annapurna, du Langtang et du camp de base de l\'Everest.','Always on'=>'Toujours actif','Analytical Cookies'=>'Cookies analytiques','Anti-Corruption and Fair Trade Policy'=>'Politique anti-corruption et commerce équitable','Any disputes shall be governed by the <strong>laws of Nepal</strong>, and legal proceedings will take place in <strong>Kathmandu District Court</strong>.'=>'Tout litige sera régi par les <strong>lois du Népal</strong>, et les procédures judiciaires se dérouleront devant le <strong>tribunal de district de Katmandou</strong>.','Any price'=>'Tous les prix','Application and submission, for straightforward cases where your documents are largely ready'=>'Constitution et dépôt du dossier, pour les cas simples où vos documents sont déjà largement prêts','Appointment and biometrics guidance'=>'Accompagnement pour le rendez-vous et les données biométriques','are requested to apply in Nepalese Embassy or other Nepalese diplomatic missions as there is no provision of on arrival visa for them.'=>'doivent en faire la demande auprès de l\'ambassade du Népal ou d\'une autre mission diplomatique népalaise, aucun visa à l\'arrivée n\'étant prévu pour eux.','Arriving in Nepal'=>'Arriver au Népal','Article'=>'Article','Article categories'=>'Catégories d\'articles','Article pages'=>'Pages d\'articles','Articles'=>'Articles','articles'=>'articles','Ask us to correct or update any information that is wrong or out of date.'=>'Demandez-nous de corriger ou de mettre à jour toute information erronée ou obsolète.','Association'=>'Association','At iFly Nepal Team, we believe in the transformative power of travel. We understand that our journey is intertwined with the communities and environments we explore. As a responsible travel agency based in Nepal, we are committed to making a positive impact on the world around us.'=>'Chez iFly Nepal, nous croyons au pouvoir transformateur du voyage. Nous savons que notre parcours est étroitement lié aux communautés et aux environnements que nous explorons. En tant qu\'agence de voyage responsable basée au Népal, nous nous engageons à avoir un impact positif sur le monde qui nous entoure.','At iFly Nepal, we believe that tourism should benefit <strong>people, planet, and prosperity</strong>. As a responsible travel company, we are committed to ensuring that our operations protect the natural environment, uplift local communities, and celebrate cultural heritage while providing life-changing experiences for our travellers.'=>'Chez iFly Nepal, nous sommes convaincus que le tourisme doit profiter <strong>aux personnes, à la planète et à la prospérité</strong>. En tant qu’agence de voyage responsable, nous nous engageons à faire en sorte que nos activités protègent l’environnement naturel, favorisent le développement des communautés locales et mettent en valeur le patrimoine culturel, tout en offrant à nos voyageurs des expériences qui changent leur vie.','At iFly Nepal, we believe travel should be more than just ticking destinations off a list. It should inspire, connect, and empower. Whether you&rsquo;re trekking through the world&rsquo;s tallest mountains, meditating in a remote monastery, sharing a meal with a village family, or joining a cultural dance workshop, we want you to experience Nepal, not just see it.'=>'Chez iFly Nepal, nous croyons que voyager doit être plus que cocher des destinations sur une liste. Cela doit inspirer, connecter et donner du pouvoir. Que vous trekiez dans les plus hautes montagnes du monde, méditiez dans un monastère isolé, partagiez un repas avec une famille de village ou participiez à un atelier de danse culturelle, nous voulons que vous viviez le Népal, pas seulement que vous le voyiez.','Attacks against tourists, Crime, Scams and Theft are very rare.'=>'Les agressions envers les touristes, la criminalité, les arnaques et les vols sont très rares.','Australia'=>'Australie','Author'=>'Auteur','Authors'=>'Auteurs','Automatically Collected Information'=>'Informations collectées automatiquement','Avoid activities or purchases that exploit wildlife or people.'=>'Évitez les activités ou les achats qui exploitent la faune sauvage ou les personnes.','Avoid and discourage purchase of <strong>illicit or unsustainable souvenirs</strong>.'=>'Éviter et décourager l\'achat de <strong>souvenirs illicites ou non durables</strong>.','Award badge'=>'Badge de récompense','Ayush, global representative in Japan'=>'Ayush, représentant mondial au Japon','b. Chinese citizen'=>'b. Citoyen chinois','Back to top'=>'Retour en haut de la page','Basic'=>'Essentiel','Basic document collection and arrangement'=>'Collecte et organisation de base des documents','Basic First Aid Kit:'=>'Trousse de premiers secours de base :','Basic Learner’s English/Nepali dictionary.'=>'Dictionnaire anglais/népalais pour débutant.','Basket'=>'Panier','Before anything goes in, we run one last checklist against your file to catch anything that might have been missed.'=>'Avant tout dépôt, nous effectuons une dernière vérification de votre dossier pour repérer tout élément qui aurait pu être oublié.','Before you fill out a single form, we sit down with you to understand where you are travelling, why, and what that embassy expects. You leave knowing exactly which visa fits your situation.'=>'Avant de remplir le moindre formulaire, nous prenons le temps de comprendre où vous voyagez, pourquoi, et ce que l\'ambassade attend. Vous repartez en sachant exactement quel visa correspond à votre situation.','Before you go'=>'Avant de partir','Blog'=>'Blog','Blog categories'=>'Catégories de blog','Blog pages'=>'Pages de blog','Blogs'=>'Blogs','blogs'=>'blogs','Booking & Payment'=>'Réservation et paiement','Booking and contact data'=>'Données de réservation et de contact','Booking data may be securely transferred to <strong>local service providers</strong> as needed for trip operations.'=>'Les données de réservation peuvent être transmises en toute sécurité à <strong>des prestataires de services locaux</strong> si cela s\'avère nécessaire pour l\'organisation du voyage.','Books/materials on teaching English/English Grammar for your reference.'=>'Livres/matériel pour l\'enseignement de l\'anglais/grammaire anglaise, à titre de référence.','Breadcrumb'=>'Fil d\'Ariane','Bring travellers and suppliers into our sustainability efforts, not around them.'=>'Impliquer les voyageurs et les prestataires dans nos efforts de durabilité, et non les tenir à l\'écart.','Browse all Nepal guides'=>'Parcourir tous les guides du Népal','Browse every article'=>'Parcourir tous les articles','Browse every blog'=>'Parcourir tous les blogs','Business Development Lead'=>'Responsable du développement commercial','Business Development, France'=>'Développement commercial, France','Business Development, USA'=>'Développement commercial, États-Unis','Business Visa'=>'Visa affaires','By booking, you agree to participate at your own risk and release iFly Nepal and its representatives from any liability related to injury, loss, or damage.'=>'En réservant, vous acceptez de participer à vos propres risques et dégagez iFly Nepal et ses représentants de toute responsabilité liée à des blessures, pertes ou dommages.','By confirming your booking with iFly Nepal, you acknowledge that you have <strong>read, understood, and agreed</strong> to these Terms &amp; Conditions.'=>'En confirmant votre réservation avec iFly Nepal, vous reconnaissez avoir <strong>lu, compris et accepté</strong> les présentes conditions générales.','By iFly Nepal'=>'Par iFly Nepal','By the client'=>'Par le client','By the client and by iFly Nepal'=>'Par le client et par iFly Nepal','By travelling with us, you agree to uphold our %s and contribute to responsible tourism in Nepal.'=>'En voyageant avec nous, vous acceptez de respecter notre %s et de contribuer à un tourisme responsable au Népal.','Calendar'=>'Calendrier','Can I combine a Nepal tour with a retreat?'=>'Puis-je combiner un circuit au Népal avec une retraite ?','Canada'=>'Canada','Cancellation & Refund Policy'=>'Politique d\'annulation et de remboursement','Certain trips (e.g. trekking, volunteering, wellness retreats) require a <strong>minimum level of physical fitness</strong>.'=>'Certains voyages (trek, bénévolat, retraites bien-être) nécessitent un <strong>niveau minimum de forme physique</strong>.','Changes to This Policy'=>'Modifications de cette politique','Chat bubble'=>'Bulle de discussion','Cheers ensure your safety during your volunteer placement in Nepal, and to make sure you are placed in a safe environment while volunteering.'=>'Nous veillons à votre sécurité durant votre mission de bénévolat au Népal et à ce que vous soyez placé dans un environnement sûr.','Chief Executive'=>'Directeur général','Choose <strong>eco-certified accommodation</strong> and transport services.'=>'Choisir des <strong>hébergements et services de transport éco-certifiés</strong>.','Clear search'=>'Effacer la recherche','Clear this filter'=>'Effacer ce filtre','Climate'=>'Climat','Climate of Nepal'=>'Climat du Népal','Climatic conditions of Nepal vary from one place to another in accordance with their geographical features. In the north summers are cool and winters severe, while in the south summers are tropical and winters are mild. Nepal has five seasons: spring, summer, monsoon, autumn and winter.'=>'Les conditions climatiques au Népal varient d\'un endroit à l\'autre en fonction des caractéristiques géographiques. Au nord, les étés sont frais et les hivers rigoureux, tandis qu\'au sud, les étés sont tropicaux et les hivers doux. Le Népal connaît cinq saisons : le printemps, l\'été, la mousson, l\'automne et l\'hiver.','Clock'=>'Horloge','Close navigation'=>'Fermer la navigation','Clothing:'=>'Vêtements :','Collect and arrange your documents'=>'Collecte et organisation de vos documents','Collected when you visit our site'=>'Collectées lors de votre visite sur notre site','Coloured pencils and pens, drawing books, stickers.'=>'Crayons et stylos de couleur, carnets de dessin, autocollants.','Comments'=>'Commentaires','Comments and related metadata'=>'Commentaires et métadonnées associées','Commerce has been a major occupation in Nepal since early times. Being situated at the crossroads of the ancient Trans-Himalayan trade route, trading is second nature to the Nepalese people. Foreign trade is characterized mainly by import of manufactured products and export of agricultural raw materials. Nepal imports manufactured goods and petroleum products worth about US$ 1 billion annually. The value of exports is about US$ 315 million. Woolen carpets are Nepal&rsquo;s largest export, earning the country over US$ 135 million per year. Garment exports account for more than US$ 74 million and handicraft goods bring in about US$ 1 million. Other important exports are pulses, hides and skins, jute and medicinal herbs.'=>'Le commerce est une activité majeure au Népal depuis les temps les plus reculés. Situé au carrefour de l\'ancienne route commerciale transhimalayenne, le commerce fait partie intégrante de la culture du peuple népalais. Le commerce extérieur se caractérise principalement par l’importation de produits manufacturés et l’exportation de matières premières agricoles. Le Népal importe chaque année pour environ 1 milliard de dollars américains de produits manufacturés et de produits pétroliers. La valeur des exportations s’élève à environ 315 millions de dollars américains. Les tapis en laine constituent le premier poste d’exportation du Népal, rapportant au pays plus de 135 millions de dollars américains par an. Les exportations de vêtements représentent plus de 74 millions de dollars américains et celles d’objets artisanaux environ 1 million de dollars américains. Parmi les autres exportations importantes figurent les légumineuses, les cuirs et peaux, le jute et les plantes médicinales.','Community Empowerment'=>'Autonomisation des communautés','Complaints & Disputes'=>'Réclamations et litiges','Complete visa assistance, for applications with financial documents, sponsors, or an interview stage'=>'Assistance visa complète, pour les demandes avec documents financiers, garants ou entretien','Comply with <strong>Nepal’s labour laws</strong> and international human rights standards.'=>'Respecter le <strong>droit du travail népalais</strong> et les normes internationales relatives aux droits humains.','Comply with legal requirements or resolve disputes.'=>'Respecter les obligations légales ou résoudre des litiges.','Conditions'=>'Conditions','Confirming your booking'=>'Confirmation de votre réservation','Conifer forest on the lower slopes of the Himalaya'=>'Forêt de conifères sur les contreforts de l\'Himalaya','Contact <em>Us</em>'=>'<em>Contactez</em>-nous','Contact <span class="underline">Us</span>'=>'<span class="underline">Contactez</span>-nous','Contact Lenses (if applicable):'=>'Lentilles de contact (le cas échéant) :','Contact Us'=>'Contactez-nous','Contribution at <span class="ink-mark">iFly Nepal<i class="ink-line"></i></span>'=>'Contribution sur <span class="ink-mark">iFly Nepal<i class="ink-line"></i></span>','Contributors'=>'Contributeurs','Cookie %s'=>'%s des cookies','Cookie <span class="underline">Policy</span>'=>'<span class="underline">Politique</span> de cookies','Cookie Management'=>'Gestion des cookies','Cookie Policy'=>'Politique de cookies','Cookies & Tracking Technologies'=>'Cookies et technologies de suivi','Cookies are <strong>small data files stored on your device</strong> when you visit our site. They help us improve your experience, remember your preferences, and analyse site traffic.'=>'Les cookies sont de <strong>petits fichiers de données stockés sur votre appareil</strong> lorsque vous visitez notre site. Ils nous aident à améliorer votre expérience, à mémoriser vos préférences et à analyser le trafic du site.','Copy link'=>'Copier le lien','Core value 1'=>'Valeur fondamentale 1','Core value 2'=>'Valeur fondamentale 2','Core value 3'=>'Valeur fondamentale 3','Core value 4'=>'Valeur fondamentale 4','Corrections or updates'=>'Corrections ou mises à jour','Country'=>'Pays','Cover and explanation letter preparation'=>'Préparation de la lettre de motivation et d\'explication','Creative Supplies:'=>'Fournitures créatives :','Cross-checking consistency across all documents'=>'Vérification croisée de la cohérence de tous les documents','CSR'=>'RSE','CTA'=>'CTA','Cultural & Heritage Sensitivity'=>'Sensibilité culturelle et patrimoniale','Cultural Workshops &amp; Experiences'=>'Ateliers et expériences culturelles','Currency:'=>'Devise :','Customise content and offers.'=>'Personnaliser le contenu et les offres.','Customise itineraries and provide personalised experiences.'=>'Personnalisez les itinéraires et proposez des expériences sur mesure.','Data Security'=>'Sécurité des données','Deletion of your data'=>'Suppression de vos données','Deposits, balances and confirmation'=>'Acomptes, soldes et confirmation','Detailed review of every document'=>'Examen détaillé de chaque document','Disaster Relief and Resilience:'=>'Aide aux sinistrés et résilience :','Discourage single-use plastics and promote <strong>refillable water systems</strong>.'=>'Décourager les plastiques à usage unique et promouvoir les <strong>systèmes d\'eau rechargeables</strong>.','Document checklist for your specific visa type'=>'Liste des documents requis pour votre type de visa','Document Preparation &amp; Review'=>'Préparation et vérification des documents','Documentation:'=>'Documentation :','Dollar sign'=>'Symbole dollar','Dramatic Himalayan mountains at the end of a Nepal journey'=>'Spectaculaires montagnes de l\'Himalaya à la fin d\'un voyage au Népal','During the mid-19th Century Jung Bahadur Rana became Nepal&rsquo;s first prime minister to wield absolute power relegating the Shah king to mere figureheads. He started a hereditary reign of the Rana Prime Ministers that lasted for 104 years. The Ranas were overthrown in a democracy movement of the early 1950s with support from the-then monarch of Nepal, King Tribhuvan. Soon after the overthrow of the Ranas, King Tribhuvan was reinstated as the Head of the State. In early 1959, Tribhuvan&rsquo;s son King Mahendra issued a new constitution, and the first democratic elections for a national assembly were held. The Nepali Congress Party was victorious and their leader, Bishweshwar Prasad Koirala formed a government and served as prime minister. But by 1960, King Mahendra had changed his mind and dissolved Parliament, dismissing the first democratic government.'=>'Au milieu du XIXe siècle, Jung Bahadur Rana devint le premier Premier ministre du Népal à exercer un pouvoir absolu, reléguant le roi Shah à un rôle de simple figure symbolique. Il instaura un règne héréditaire des Premiers ministres Rana qui dura 104 ans. Les Rana furent renversés lors d\'un mouvement démocratique du début des années 1950, soutenu par le monarque de l\'époque, le roi Tribhuvan. Peu après leur chute, le roi Tribhuvan fut rétabli comme chef de l\'État. Début 1959, son fils, le roi Mahendra, promulgua une nouvelle constitution et les premières élections démocratiques pour une assemblée nationale furent organisées. Le parti du Congrès népalais l\'emporta et son dirigeant, Bishweshwar Prasad Koirala, forma un gouvernement et devint Premier ministre. Mais en 1960, le roi Mahendra changea d\'avis, dissolut le Parlement et destitua le premier gouvernement démocratique.','During their 550 year rule, the Mallas built numerous temples and splendid palaces with picturesque squares. It was also during their rule that society and the cities became well organized; religious festivals were introduced and literature, music and art were encouraged. After the death of Yaksha Malla, the valley was divided into three kingdoms: Kathmandu (Kantipur), Bhaktapur (Bhadgaon) and Patan (Lalitpur). Around this time, the Nepal as we know it today was divided into about 46 independent principalities. One among these was the kingdom of Gorkha with a Shah ruler. Much of Kathmandu Valley&rsquo;s history around this time was recorded by Capuchin friars who lived in the valley on their way in and out of Tibet. An ambitious Gorkha King named Prithvi Narayan Shah embarked on a conquering mission that led to the defeat of all the kingdoms in the valley (including Kirtipur which was an independent state) by 1769. Instead of annexing the newly acquired states to his kingdom of Gorkha, Prithvi Narayan decided to move his capital to Kathmandu establishing the Shah dynasty which ruled unified Nepal from 1769 to 2008.'=>'Au cours de leur règne de 550 ans, les Malla ont construit de nombreux temples et de splendides palais agrémentés de places pittoresques. C’est également sous leur règne que la société et les villes se sont bien organisées ; des fêtes religieuses ont été instaurées et la littérature, la musique et les arts ont été encouragés. Après la mort de Yaksha Malla, la vallée fut divisée en trois royaumes : Katmandou (Kantipur), Bhaktapur (Bhadgaon) et Patan (Lalitpur). À cette époque, le Népal tel que nous le connaissons aujourd’hui était divisé en environ 46 principautés indépendantes. L’une d’entre elles était le royaume de Gorkha, dirigé par un souverain de la dynastie des Shah. Une grande partie de l’histoire de la vallée de Katmandou à cette époque a été consignée par des frères capucins qui vivaient dans la vallée lors de leurs allers-retours vers le Tibet. Un roi de Gorkha ambitieux, Prithvi Narayan Shah, se lança dans une campagne de conquête qui aboutit, dès 1769, à la défaite de tous les royaumes de la vallée (y compris Kirtipur, qui était un État indépendant). Au lieu d’annexer les États nouvellement acquis à son royaume de Gorkha, Prithvi Narayan décida de transférer sa capitale à Katmandou, fondant ainsi la dynastie des Shah qui régna sur le Népal unifié de 1769 à 2008.','Economy'=>'Économie','Editable by you at any time'=>'Modifiables par vous à tout moment','Educate clients and guides on responsible trekking and <strong>Leave No Trace</strong> principles.'=>'Sensibiliser clients et guides au trekking responsable et aux principes <strong>Leave No Trace</strong>.','Education for All:'=>'Éducation pour tous :','Educational Resources:'=>'Ressources éducatives :','Eight out of 10 Nepalese are engaged in farming and it accounts for more than 40% of the GDP. Rolling fields and neat terraces can be seen all over the Terai flatlands and the hills of Nepal. Even in the highly urbanized Kathmandu Valley, large tracts of land outside the city areas are devoted to farming. Rice is the staple diet in Nepal and around three million tons are produced annually. Other major crops are maize, wheat, millet and barley. Besides food grains, Cash crops Like Sugarcane, oil seeds, tobacco, jute and tea are also cultivated in large quantities.'=>'Huit Népalais sur dix travaillent dans l\'agriculture, qui représente plus de 40 % du PIB. Des champs vallonnés et des terrasses soignées couvrent les plaines du Teraï et les collines du Népal. Même dans la vallée de Katmandou, très urbanisée, de vastes étendues situées hors des zones urbaines sont consacrées à l\'agriculture. Le riz est l\'aliment de base du Népal, avec environ trois millions de tonnes produites chaque année. Le maïs, le blé, le millet et l\'orge comptent parmi les autres cultures majeures. Outre les céréales vivrières, des cultures de rente comme la canne à sucre, les oléagineux, le tabac, le jute et le thé sont également cultivées en grande quantité.','Email'=>'E-mail','Email Address'=>'Adresse e-mail','Embedded content'=>'Contenu intégré','Embedded Content from Other Websites'=>'Contenu intégré provenant d\'autres sites web','Empower the local communities who host and guide our travellers.'=>'Donner les moyens d\'agir aux communautés locales qui accueillent et accompagnent nos voyageurs.','Empowering Local Communities:'=>'Renforcer l\'autonomie des communautés locales :','Encourage porters and staff to <strong>collect waste on trails</strong> where possible.'=>'Encourager les porteurs et le personnel à <strong>collecter les déchets sur les sentiers</strong> dans la mesure du possible.','Encourage travellers to shop, eat, and stay local.'=>'Encouragez les voyageurs à faire leurs achats, à se restaurer et à séjourner dans la région.','Engage clients and partners'=>'Impliquer les clients et les partenaires','Engage travellers through <strong>pre-departure materials</strong> and on-trip education.'=>'Sensibiliser les voyageurs via des <strong>supports avant le départ</strong> et une éducation pendant le voyage.','Ensure <strong>fair wages, safe working conditions, and insurance</strong> for all staff and field crew.'=>'Garantir des <strong>salaires équitables, des conditions de travail sûres et une assurance</strong> pour tout le personnel et les équipes de terrain.','Environmental Responsibility'=>'Responsabilité environnementale','Essential Cookies'=>'Cookies essentiels','Establish a <strong>grievance mechanism</strong> for local stakeholders.'=>'Mettre en place un <strong>mécanisme de traitement des réclamations</strong> à l\'intention des parties prenantes locales.','Ethical Business Conduct'=>'Conduite commerciale éthique','Ethnic Diversity in the Kathmandu Valley'=>'Diversité ethnique dans la vallée de Katmandou','Every effort will be made to provide <strong>comparable alternatives</strong> with minimal disruption.'=>'Tous les efforts seront faits pour proposer des <strong>alternatives comparables</strong> avec un minimum de désagrément.','Every trek and tour is led by licensed guides who know the trails, culture and language.'=>'Chaque trek et circuit est mené par des guides agréés qui connaissent les sentiers, la culture et la langue.','Everything in Basic'=>'Tout ce qui est inclus dans Essentiel','Experience'=>'Expérience','Experienced guides'=>'Guides expérimentés','Experienced Local Guides'=>'Guides locaux expérimentés','Expertise:'=>'Domaines d\'expertise :','Explore'=>'Explorer','Explore %s'=>'Explorer %s','Explore Experiences'=>'Découvrez nos expériences','Explore Nepal'=>'Explorer le Népal','Explore the iconic trails of Everest, Annapurna, and Langtang, or venture into the remote corners of Mustang, Dolpo, or Kanchenjunga. Our experienced, licensed guides&mdash;including female trekking leaders&mdash;prioritize your safety, comfort, and connection with nature.'=>'Explorez les sentiers emblématiques de l\'Everest, de l\'Annapurna et du Langtang, ou aventurez-vous dans les coins reculés du Mustang, du Dolpo ou du Kangchenjunga. Nos guides expérimentés et agréés&mdash;dont des guides de trek féminines&mdash;font de votre sécurité, de votre confort et de votre connexion à la nature une priorité.','Face mask (depending on the time of year, Kathmandu can become very polluted and dusty).'=>'Masque facial (selon la période de l\'année, Katmandou peut devenir très pollué et poussiéreux).','Facilitate voluntourism programmes with <strong>genuine community benefit</strong>.'=>'Faciliter des programmes de tourisme solidaire avec un <strong>bénéfice réel pour la communauté</strong>.','Factory'=>'Usine','Fair Employment & Human Rights'=>'Emploi équitable et droits humains','Fair wages, safe conditions and insurance for all staff and field crew.'=>'Salaires équitables, conditions sûres et assurance pour tout le personnel et les équipes de terrain.','Family &amp; Dependent Visa'=>'Visa familial et de personne à charge','Farmers planting rice in Chitwan, Nepal'=>'Agriculteurs plantant du riz à Chitwan, au Népal','Feedback, comments, or questions submitted via forms.'=>'Retours, commentaires ou questions soumis via des formulaires.','Festival lamps during a Nepali celebration'=>'Lampes de festival lors d\'une célébration népalaise','Fields'=>'Champs','Fields marked * are required.'=>'Les champs marqués * sont obligatoires.','Fill out your application'=>'Remplissez votre demande','Filter departures by month'=>'Filtrer les départs par mois','Filter featured experiences'=>'Filtrer les expériences à ne pas manquer','Final Acceptance'=>'Acceptation finale','Final quality review of your full application'=>'Contrôle qualité final de l\'ensemble de votre dossier','Final submission checklist'=>'Liste de vérification avant soumission finale','Finance'=>'Finance','Financial and bank statement review'=>'Vérification des documents financiers et relevés bancaires','Find a Retreat'=>'Trouver une retraite','Find My Trip'=>'Trouver mon voyage','Fleece jacket (during winter months)'=>'Polaire (durant les mois d\'hiver)','Flight Delays & Cancellations'=>'Retards et annulations de vols','Flights across Nepal, particularly in high mountain areas, can be delayed due to poor weather conditions.'=>'Les vols à travers le Népal, en particulier dans les zones de haute montagne, peuvent être retardés en raison de mauvaises conditions météorologiques.','Flip-flops'=>'Tongs','Flora & fauna'=>'Flore & faune','Flora and Fauna'=>'Flore et faune','Follow us'=>'Suivez-nous','Food & Beverage'=>'Restauration','Footwear:'=>'Chaussures :','For holidays, sightseeing, and short family visits abroad.'=>'Pour les vacances, le tourisme et les courtes visites familiales à l\'étranger.','For joining a husband, wife, or partner already settled overseas.'=>'Pour rejoindre un mari, une épouse ou un partenaire déjà installé à l\'étranger.','For joining parents or children abroad, including Ex-British Gurkha family cases.'=>'Pour rejoindre des parents ou des enfants à l\'étranger, y compris les cas de familles d\'anciens Gurkhas britanniques.','For meetings, conferences, and short-term work trips.'=>'Pour les réunions, conférences et déplacements professionnels de courte durée.','For trekking, Never trek alone. Use a reputable agency, remain on established routes, and walk with at least one other person.'=>'Pour le trek, ne partez jamais seul. Faites appel à une agence réputée, restez sur les itinéraires établis et marchez avec au moins une autre personne.','Forbidden Souvenirs & Wildlife Protection Policy'=>'Politique sur les souvenirs interdits et la protection de la faune','Foreigner who have stayed here without renewing visa, need to pay Nepalese currency equivalent to US $ 3 per day along with the reqired extension fee.'=>'Tout étranger resté sur place sans renouveler son visa doit payer l\'équivalent en roupies népalaises de 3 USD par jour, en plus des frais de prolongation requis.','Foreigner who intends to visit Nepal must hold valid passport or any travel document equivalent to passport issued by the government. for visiting a foreign country prior to apply for visa.'=>'Tout étranger souhaitant visiter le Népal doit être en possession d\'un passeport valide ou d\'un document de voyage équivalent délivré par un gouvernement, avant de faire une demande de visa.','Foreigners, who have already overstayed for more than 150 days without renewing tourist visa shall be levied the fees referred in clause 2(c) and a penalty of Rs 50,000 as per the Immigration Act.'=>'Les étrangers ayant déjà dépassé 150 jours de séjour sans renouveler leur visa touristique se verront appliquer les frais mentionnés à la clause 2(c) ainsi qu\'une pénalité de 50 000 Rs conformément à la loi sur l\'immigration.','Forested middle hills and river valleys of Nepal'=>'Collines moyennes boisées et vallées fluviales du Népal','Formal complaints must be submitted <strong>in writing within 14 days</strong> of the trip&#8217;s conclusion.'=>'Les réclamations officielles doivent être soumises <strong>par écrit dans les 14 jours</strong> suivant la fin du voyage.','Foster cultural sensitivity'=>'Favoriser la sensibilité culturelle','Founded in 2021 in the vibrant city of Kathmandu, iFly Nepal is more than just a travel company&mdash;we are a collective of explorers, storytellers, and community advocates dedicated to creating travel experiences that leave lasting impressions. Locally owned and deeply rooted in Nepali culture, our team understands the soul of this land&mdash;and we want you to feel it too.'=>'Fondée en 2021 dans la ville animée de Katmandou, iFly Nepal est bien plus qu’une simple agence de voyage : nous sommes un collectif d’explorateurs, de conteurs et de défenseurs de la communauté, qui se consacre à la création d’expériences de voyage laissant un souvenir inoubliable. Détenue par des locaux et profondément ancrée dans la culture népalaise, notre équipe comprend l’âme de cette terre — et nous voulons que vous la ressentiez vous aussi.','Four categories'=>'Quatre catégories','Four kinds, and <span class="underline">what each does</span>'=>'Quatre types, et <span class="underline">ce que fait chacun</span>','From booking your biometrics slot to preparing you for a consular interview, we help you walk in ready and walk out with a clean application on record.'=>'De la prise de rendez-vous biométrique à la préparation de votre entretien consulaire, nous vous aidons à vous présenter prêt et à repartir avec un dossier impeccable.','From teaching in rural schools to working on permaculture farms or shadowing in local clinics, we offer meaningful placements for travelers who want to give back. Our volunteer programs are thoughtfully developed with community needs in mind.'=>'Qu\'il s\'agisse d\'enseigner dans des écoles rurales, de travailler dans des fermes pratiquant la permaculture ou d\'observer le fonctionnement de cliniques locales, nous proposons des missions enrichissantes aux voyageurs qui souhaitent s\'investir. Nos programmes de bénévolat sont soigneusement élaborés en tenant compte des besoins des communautés.','From the articles'=>'Depuis les articles','From the blog'=>'Depuis le blog','Full Name'=>'Nom complet','Full refund minus transaction &amp; admin fees'=>'Remboursement intégral, moins les frais de transaction et de dossier','Functional Cookies'=>'Cookies fonctionnels','Geography'=>'Géographie','Get directions'=>'Obtenir l\'itinéraire','Get in touch'=>'Contactez-nous','Get your document checklist'=>'Obtenez votre liste de documents','Globe'=>'Globe','Good to know is that on average temperatures drop 6&deg;C for every 1,000 m you gain in altitude. The Himalayas act as a barrier to the cold winds blowing from Central Asia in winter, and forms the northern boundary of the monsoon wind patterns. Eighty percent of all the rain in Nepal is received during the monsoon (June-September). Winter rains are more pronounced in the western hills. The average annual rainfall is 1,600 mm, but it varies by eco-climatic zones, such as 3,345 mm in Pokhara and below 300 mm in Mustang.'=>'Bon à savoir : la température baisse en moyenne de 6&deg;C tous les 1 000 m d\'altitude gagnés. L\'Himalaya fait office de barrière contre les vents froids venus d\'Asie centrale en hiver, et forme la limite nord des régimes de mousson. Quatre-vingts pour cent des précipitations annuelles du Népal tombent pendant la mousson (juin-septembre). Les pluies hivernales sont plus marquées dans les collines de l\'ouest. Les précipitations annuelles moyennes sont de 1 600 mm, mais varient selon les zones éco-climatiques, allant de 3 345 mm à Pokhara à moins de 300 mm au Mustang.','Google Reviews'=>'Avis Google','Governance & Management'=>'Gouvernance et gestion','Guide'=>'Guide','Gus, global representative in the UK'=>'Gus, représentant mondial au Royaume-Uni','Head Office'=>'Siège social','Head office'=>'Siège social','Health & Fitness'=>'Santé et forme physique','Health and Well-being:'=>'Santé et bien-être :','Healthcare professionals supporting community wellbeing'=>'Professionnels de santé soutenant le bien-être communautaire','Heritage architecture in the Kathmandu Valley'=>'Architecture patrimoniale dans la vallée de Katmandou','High Himalayan terrain in northern Nepal'=>'Terrain himalayen d\'altitude dans le nord du Népal','Highest point'=>'Point culminant','Hiking boots'=>'Chaussures de randonnée','Historic architecture and living cultural heritage in Kathmandu'=>'Architecture historique et patrimoine culturel vivant à Katmandou','Historic architecture in Kathmandu, Nepal'=>'Architecture historique à Katmandou, au Népal','History'=>'Histoire','Hold <strong>biannual internal reviews</strong> and sustainability training sessions.'=>'Organiser des <strong>revues internes semestrielles</strong> et des sessions de formation à la durabilité.','Home'=>'Accueil','How issues are resolved'=>'Comment les problèmes sont résolus','How it earns'=>'Comment il gagne sa vie','How it got here'=>'Comment il en est arrivé là','How it is governed'=>'Comment il est gouverné','How Long We Retain Your Data'=>'Combien de temps nous conservons vos données','How many days should I spend in Nepal?'=>'Combien de jours dois-je prévoir pour le Népal ?','How we keep it honest'=>'Comment nous restons transparents','How we safeguard your data'=>'Comment nous protégeons vos données','How We Use Your Information'=>'Comment nous utilisons vos informations','However, foreigner visitors, who have entered the country towards the end of a visa year, can use the remainder of his visa period in another visa year.'=>'Toutefois, les visiteurs étrangers entrés dans le pays vers la fin d\'une année de visa peuvent utiliser le reste de leur période de visa au cours d\'une autre année de visa.','I have'=>'J\'ai','I want to'=>'Je veux','Identifying weak or missing documents, with fixes'=>'Identification des documents manquants ou insuffisants, avec correctifs','If cancellation is due to <strong>force majeure</strong>, we are not liable for compensation beyond the refund of received payments.'=>'Si l\'annulation est due à un <strong>cas de force majeure</strong>, notre responsabilité se limite au remboursement des paiements reçus.','If multiple entry facility is required to be valid for the renewed period, additional US $ 20 along with fees prescribed in 2 (a) has to be paid.'=>'Si un visa à entrées multiples est requis pour la période renouvelée, 20 USD supplémentaires doivent être versés en plus des frais prévus au point 2(a).','If we cancel due to unforeseen events (e.g. natural disasters, political unrest), a <strong>full refund or credit</strong> will be offered.'=>'Si nous annulons en raison d\'événements imprévus (catastrophes naturelles, troubles politiques, etc.), un <strong>remboursement intégral ou un avoir</strong> vous sera proposé.','If you are using <strong>Gravatar</strong>, an anonymised email string may be used to display your profile photo.'=>'Si vous utilisez <strong>Gravatar</strong>, une chaîne anonymisée de votre adresse e-mail peut être utilisée pour afficher votre photo de profil.','If you encounter any issues during your trip, notify your guide or contact us <strong>immediately</strong> so we can resolve it.'=>'Si vous rencontrez un problème pendant votre voyage, prévenez votre guide ou contactez-nous <strong>immédiatement</strong> afin que nous puissions le résoudre.','If you plan to go trekking during your stay in Nepal you are advised to use reputable trekking agencies, to keep to established routes, and to always walk in groups. Trekking alone is not recommended.'=>'Si vous prévoyez de faire du trek pendant votre séjour au Népal, il est conseillé de faire appel à des agences de trek réputées, de rester sur les itinéraires établis et de toujours marcher en groupe. Le trek en solitaire n\'est pas recommandé.','If you upload images (e.g. in blog comments), we advise <strong>removing embedded location data (EXIF GPS)</strong>, as visitors may extract such data.'=>'Si vous téléversez des images (par exemple dans les commentaires de blog), nous vous conseillons de <strong>retirer les données de localisation intégrées (EXIF GPS)</strong>, car les visiteurs peuvent les extraire.','iFly Nepal is not liable for personal disputes, loss, or misunderstandings during placements.'=>'iFly Nepal ne saurait être tenu responsable des différends personnels, pertes ou malentendus survenant durant les missions.','iFly Nepal is not responsible for expenses resulting from your failure to secure proper insurance.'=>'iFly Nepal n\'est pas responsable des frais résultant d\'une absence d\'assurance adéquate de votre part.','iFly Nepal is not responsible for visa denials, immigration issues, or delays caused by border regulations.'=>'iFly Nepal n\'est pas responsable des refus de visa, des problèmes d\'immigration ou des retards causés par la réglementation frontalière.','iFly Nepal on Google Maps'=>'iFly Nepal sur Google Maps','iFly Nepal&#8217;s guides are trained in <strong>first aid and altitude safety</strong> and carry basic medical kits and emergency protocols.'=>'Les guides d\'iFly Nepal sont formés aux <strong>premiers secours et à la sécurité en altitude</strong> et disposent de trousses médicales de base et de protocoles d\'urgence.','Images you share with us'=>'Images que vous partagez avec nous','Improving your browsing experience'=>'Amélioration de votre expérience de navigation','In 1998, a total of 463,684 tourists visited Nepal, making tourism one of the largest industries in the Kingdom. This sector has been expanding rapidly since its inception in the 1950. Thanks to Nepal&rsquo;s natural beauty, rich cultural heritage and the diversity of sight-seeing and adventure opportunities available. At one time, tourism used to be the biggest foreign currency earner for the country. Nepal earned over US$ 152 million from tourism in 1998.'=>'En 1998, un total de 463 684 touristes ont visité le Népal, faisant du tourisme l\'une des plus grandes industries du royaume. Ce secteur connaît une expansion rapide depuis ses débuts dans les années 1950, grâce à la beauté naturelle du Népal, à son riche patrimoine culturel et à la diversité des activités touristiques et d\'aventure proposées. Le tourisme fut autrefois la principale source de devises étrangères du pays. Le Népal a généré plus de 152 millions de dollars US grâce au tourisme en 1998.','In 2008 a Constituent Assembly was sworn in following a democratic election and the Constituent Assembly declared Nepal a republic.'=>'En 2008, une Assemblée constituante fut assermentée à la suite d\'une élection démocratique, et déclara le Népal république.','In serious situations, we may organise <strong>helicopter evacuation at the traveller&#8217;s expense</strong> unless covered by insurance.'=>'Dans les situations graves, nous pouvons organiser une <strong>évacuation par hélicoptère aux frais du voyageur</strong>, sauf si celle-ci est couverte par une assurance.','In the Field'=>'Sur le terrain','In the Office'=>'Au bureau','In the Terai (south Nepal), summer temperatures exceed 37&deg; C and higher in some areas, winter temperatures range from 7&deg;C to 23&deg;C in the Terai. In mountainous regions, hills and valleys, summers are temperate while winter temperatures can plummet under sub zero. The Kathmandu Valley has a pleasant climate with average summer and winter temperatures of 19&deg;C &ndash; 35&deg;C and 2&deg;C &ndash; 12&deg;C respectively.'=>'Dans le Teraï (sud du Népal), les températures estivales dépassent 37&deg;C et plus encore dans certaines zones ; les températures hivernales varient de 7&deg;C à 23&deg;C. Dans les régions montagneuses, collines et vallées, les étés sont tempérés tandis que les températures hivernales peuvent descendre bien en dessous de zéro. La vallée de Katmandou bénéficie d\'un climat agréable, avec des températures moyennes estivales et hivernales de respectivement 19&deg;C à 35&deg;C et 2&deg;C à 12&deg;C.','Include sustainability feedback in <strong>client post-trip evaluations</strong>.'=>'Inclure les retours sur la durabilité dans les <strong>évaluations post-voyage des clients</strong>.','Information We Collect'=>'Informations que nous collectons','Insect Protection:'=>'Protection contre les insectes :','Interview preparation, where applicable'=>'Préparation à l\'entretien, le cas échéant','Introduction'=>'Introduction','Invest in community projects such as <strong>school support, health care, and training</strong>.'=>'Investir dans des projets communautaires tels que le <strong>soutien scolaire, les soins de santé et la formation</strong>.','It is your responsibility to consult with a physician and ensure you are in good health before participating.'=>'Il est de votre responsabilité de consulter un médecin et de vous assurer d\'être en bonne santé avant de participer.','Italy'=>'Italie','Japan'=>'Japon','Kathmandu'=>'Katmandou','Kathmandu Durbar Square in Nepal'=>'Place Durbar de Katmandou, au Népal','Kathmandu office · usually replies within a day'=>'Bureau de Katmandou · répond généralement sous un jour','Keep %s.'=>'Conserver %s.','Keeping you informed'=>'Vous tenir informé','Lake and mountain landscape in Nepal'=>'Paysage de lac et de montagne au Népal','Language Aid:'=>'Aide linguistique :','Latest'=>'Récent','Latest from Kathmandu'=>'Dernières nouvelles de Katmandou','Latest news'=>'Dernières actualités','Law and technology change'=>'Le droit et la technologie évoluent','Leaf'=>'Feuille','Legal links'=>'Liens juridiques','Less than 15 days prior'=>'Moins de 15 jours avant','Licensed & Certified'=>'Agréé et certifié','Light-weight cotton clothing'=>'Vêtements légers en coton','Link copied'=>'Lien copié','Listed with Nepal Tourism Board, TAAN, NMA and KEEP — memberships you can check.'=>'Enregistré auprès du Nepal Tourism Board, de TAAN, de NMA et de KEEP — des adhésions vérifiables.','Local Employment Opportunities:'=>'Offres d\'emploi locales :','Local Nepal team'=>'Équipe locale au Népal','Lowland forest and grassland wildlife habitat in the Terai'=>'Forêt de plaine et habitat faunique de prairie dans le Teraï','Maintain a <strong>safe, inclusive, and harassment-free</strong> workplace.'=>'Maintenir un environnement de travail <strong>sûr, inclusif et exempt de harcèlement</strong>.','Make space for meditation, yoga, Ayurveda, monastery life and restorative experiences shaped by Nepal\'s spiritual traditions and natural landscapes.'=>'Faites place à la méditation, au yoga, à l\'Ayurveda, à la vie monastique et à des expériences réparatrices inspirées des traditions spirituelles et des paysages naturels du Népal.','Make sure your insurance covers your basic health insurance.'=>'Assurez-vous que votre assurance couvre au minimum les frais de santé essentiels.','Mandatory cover'=>'Couverture obligatoire','Manufacturing'=>'Industrie manufacturière','Manufacturing is still at the developmental stage and it represents less than 10% of the GDP. Major industries are woolen carpets, garments, textiles, leather products, paper and cement. Other products made in Nepal are steel utensils, cigarettes, beverages and sugar. There are many modern large-scale factories but the majority are cottage or small scale operations. Most of Nepal&rsquo;s industries are based in the Kathmandu Valley and a string of Small towns in the southern Terai Plains.'=>'L\'industrie manufacturière en est encore au stade du développement et représente moins de 10 % du PIB. Les principaux secteurs sont les tapis en laine, les vêtements, les textiles, les produits en cuir, le papier et le ciment. Le Népal produit également des ustensiles en acier, des cigarettes, des boissons et du sucre. Il existe de nombreuses usines modernes à grande échelle, mais la majorité des opérations restent artisanales ou à petite échelle. La plupart des industries népalaises sont situées dans la vallée de Katmandou et dans une série de petites villes du sud des plaines du Teraï.','Many activities (e.g. trekking, rafting, safaris) involve inherent risks such as <strong>altitude sickness, accidents, or unforeseen events</strong>.'=>'De nombreuses activités (trek, rafting, safaris, etc.) comportent des risques inhérents tels que le <strong>mal des montagnes, les accidents ou les événements imprévus</strong>.','Map pin'=>'Épingle de carte','Max (°C)'=>'Max (°C)','Media Uploads'=>'Fichiers médias téléversés','Meditation & Wellness'=>'Méditation et bien-être','Medium'=>'Moyen','Members of the iFly Nepal team'=>'Membres de l\'équipe iFly Nepal','Message'=>'Message','Middle Hills and Valley People'=>'Les habitants des collines et de la vallée','Min (°C)'=>'Min (°C)','Minimise <strong>food waste</strong> in tours and office events.'=>'Réduire le <strong>gaspillage alimentaire</strong> lors des circuits et des événements de bureau.','Minimise our environmental footprint'=>'Réduire notre empreinte environnementale','Minimise plastic and environmental impact by using reusable gear.'=>'Réduire le plastique et l\'impact environnemental en utilisant du matériel réutilisable.','Mobile Number'=>'Numéro de mobile','Monitoring, Feedback & Continuous Improvement'=>'Suivi, retours et amélioration continue','More from the %s.'=>'Plus de %s.','More travel tips for planning your Nepal trip, from the same shelf.'=>'D\'autres conseils de voyage pour préparer votre séjour au Népal, dans la même rubrique.','Mosquito repellent'=>'Répulsif anti-moustiques','Most chosen'=>'Le plus choisi','Most travellers can obtain a Nepal visa on arrival at Tribhuvan International Airport or land borders. Ensure your passport is <strong>valid for at least 6 months</strong>.'=>'La plupart des voyageurs peuvent obtenir un visa népalais à l\'arrivée à l\'aéroport international Tribhuvan ou aux frontières terrestres. Assurez-vous que votre passeport est <strong>valide au moins 6 mois</strong>.','Mountain'=>'Montagne','Mountain flights and weather'=>'Vols en montagne et météo','Mt. Everest, 8,848 m'=>'Mont Everest, 8 848 m','My budget'=>'Mon budget','Necessary for basic site functionality — security, navigation, and booking.'=>'Nécessaires au fonctionnement de base du site — sécurité, navigation et réservation.','Nepal is a safe country to travel or volunteer. There is good access mobile phone and internet'=>'Le Népal est un pays sûr pour voyager ou faire du bénévolat. L\'accès au réseau mobile et à internet y est bon','Nepal is developing county with an agricultural economy. In recent years, the country&rsquo;s efforts to expand into manufacturing industries and other technological sectors have achieved much progress. Farming is the main economic activity followed by manufacturing, trade and tourism. The chief sources of foreign currency earnings are marchandise export, services, tourism and Gurkha remittances. The annual Gross Domestic Product (GDP) is about US$ 4.3 Billion.'=>'Le Népal est un pays en développement dont l\'économie repose sur l\'agriculture. Ces dernières années, les efforts déployés par le pays pour se diversifier dans les industries manufacturières et d\'autres secteurs technologiques ont permis de réaliser d\'importants progrès. L\'agriculture est la principale activité économique, suivie par l\'industrie manufacturière, le commerce et le tourisme. Les principales sources de recettes en devises étrangères sont les exportations de marchandises, les services, le tourisme et les transferts de fonds des Gurkhas. Le produit intérieur brut (PIB) annuel s\'élève à environ 4,3 milliards de dollars américains.','Nepal is located in South Asia between China in the north and India in the south, east and west. The total land area is 147,181 sq. km including water area of the country that is 3,830 sq. km. The geographical coordinates are 28&deg;00&prime;N 84&deg;00&prime;E. Nepal falls in the temperate zone north of the Tropic of Cancer. Nepal&rsquo;s ecological zone run east to west about 800 km along its Himalayan axis, 150 to 250 km north to south, and is vertically intersected by the river systems. The country is divided into three main geographical regions: Himalayan region, mid hill region and Terai region. The highest point in the country is Mt. Everest (8,848 m) while the lowest point is in the Terai plains of Kechana Kalan in Jhapa (60 m).'=>'Le Népal est situé en Asie du Sud, entre la Chine au nord et l\'Inde au sud, à l\'est et à l\'ouest. Sa superficie totale est de 147 181 km², dont 3 830 km² de plans d\'eau. Ses coordonnées géographiques sont 28°00′ N, 84°00′ E. Le Népal se situe dans la zone tempérée, au nord du tropique du Cancer. La zone écologique du Népal s’étend d’est en ouest sur environ 800 km le long de l’axe himalayen, de 150 à 250 km du nord au sud, et est traversée verticalement par les réseaux fluviaux. Le pays est divisé en trois grandes régions géographiques : la région himalayenne, la région des collines intermédiaires et la région du Teraï. Le point culminant du pays est le mont Everest (8 848 m), tandis que le point le plus bas se trouve dans les plaines du Teraï, à Kechana Kalan, dans le district de Jhapa (60 m).','Nepal Tours'=>'Circuits au Népal','Nepal&rsquo;s mountain environment beneath a clear sky'=>'L\'environnement montagneux du Népal sous un ciel dégagé','Nepal&rsquo;s rich cultural heritage is a treasure to be preserved. We actively promote responsible tourism practices that respect and celebrate local customs and traditions, ensuring that cultural heritage remains vibrant for generations to come.'=>'Le riche patrimoine culturel du Népal est un trésor qu’il convient de préserver. Nous encourageons activement les pratiques de tourisme responsable qui respectent et mettent en valeur les coutumes et traditions locales, afin de garantir que ce patrimoine culturel reste vivant pour les générations futures.','Nepalese currency equivalent to US $ 2 per day to renew the validity of tourist visa.'=>'Équivalent en roupies népalaises de 2 USD par jour pour renouveler la validité du visa touristique.','New Zealand'=>'Nouvelle-Zélande','News'=>'Actualités','news'=>'actualités','News Center'=>'Espace actualités','News pages'=>'Pages d\'actualités','News story'=>'Article d\'actualité','Next'=>'Suivant','Next departures'=>'Prochains départs','Next people'=>'Personnes suivantes','Next review'=>'Prochaine révision','No articles found.'=>'Aucun article trouvé.','No blogs found.'=>'Aucun blog trouvé.','No foreigner is entitled to enter into and stay in Nepal without valid visa. Tourist entry visa can be obtained for the following duration from Nepalese Embassy or Consulate or other mission offices or immigration offices located on entry points in Nepal.'=>'Aucun étranger n\'est autorisé à entrer et séjourner au Népal sans visa valide. Le visa touristique d\'entrée peut être obtenu pour les durées suivantes auprès de l\'ambassade ou du consulat népalais, ou d\'autres bureaux de mission ou d\'immigration situés aux points d\'entrée du Népal.','No news found.'=>'Aucune actualité trouvée.','No refund'=>'Aucun remboursement','No refund will be made for <strong>unused services</strong> once the trip has commenced.'=>'Aucun remboursement ne sera effectué pour les <strong>services non utilisés</strong> une fois le voyage commencé.','Northern Himalayan People'=>'Les peuples de l\'Himalaya septentrional','Northward, on the lower slopes and spurs of the great Himalayas, oaks and pines are the dominant species up to an altitude of about 2400m above which are found dense conifer forests including Picea, Tusga, Larix and Abies spp. The latter is usually confined to higher elevations with Betula typically marking the upper limit of the tree line. At about 3600 to 3900m, rhododendron, bamboo and maples are commonly associated with the coniferous zone. Composition of he forest varies considerably with coniferous predominating in the west and eracaceous in the east. The wildlife of this region includes the Himalayan bear, serow, ghoral, barking deer and wildboar, with Himalayan tahr sometimes being seen on steep rocky faces above 2400m. The red panda is among the more interesting of the mammals found in this zone; it appears to be fairly distributed in suitable areas of the forest above 1800m. The rich and varied avifauna of this region includes several spectacular and beautiful pheasants, including the Danfe pheasant, Nepal&rsquo;s national bird.'=>'Plus au nord, sur les contreforts et éperons du grand Himalaya, chênes et pins dominent jusqu\'à environ 2 400 m d\'altitude, au-delà de laquelle on trouve de denses forêts de conifères comprenant Picea, Tsuga, Larix et Abies spp. Ce dernier genre se limite généralement aux altitudes plus élevées, le bouleau marquant typiquement la limite supérieure de la forêt. Vers 3 600 à 3 900 m, rhododendrons, bambous et érables sont fréquemment associés à la zone de conifères. La composition de la forêt varie considérablement, les conifères dominant à l\'ouest et les feuillus à l\'est. La faune de cette région comprend l\'ours de l\'Himalaya, le serow, le ghoral, le muntjac et le sanglier, le tahr de l\'Himalaya étant parfois observé sur les parois rocheuses abruptes au-dessus de 2 400 m. Le panda roux est l\'un des mammifères les plus intéressants de cette zone ; il semble assez bien réparti dans les zones forestières adaptées au-dessus de 1 800 m. L\'avifaune riche et variée de cette région comprend plusieurs faisans spectaculaires, dont le faisan Danfe, oiseau national du Népal.','Not sure yet'=>'Pas encore sûr','Note'=>'Note','Nothing found.'=>'Aucun résultat.','Nothing matched. Try a trek, a region or a festival.'=>'Aucune correspondance. Essayez un trek, une région ou un festival.','Of 163 wetlands documented, the nine globally recognized Ramsar sites are: Koshi Tappu Wildlife Reserve, Beeshazarital (Chitwan), Jagdishpur Reservoir (Kapilvastu) Ghodaghodi Tal (Kailali) in the Terai, and Gokyo (Solukhumbu), Phoksundo (Dolpa), Rara (Mugu) and Mai Pokhari (Ilam) in the mountain region. There are more than 30 natural caves in the country out of which only a few are accessible by road. Maratika Cave (also known as Haleshi) is a pilgrimage site associated with Buddhism and Hinduism. Siddha Cave is near Bimalnagar along the Kathmandu-Pokhara highway. Pokhara is also known for caves namely Bats&rsquo; shed, Batulechar, Gupteswar, Patale Chhango. The numerous caves around Lo Manthang in Mustang include Luri and Tashi Kabum which house ancient murals and chhortens dating back to the 13th century.'=>'Sur les 163 zones humides documentées, les neuf sites reconnus au niveau mondial par la convention de Ramsar sont : la réserve faunique de Koshi Tappu, Beeshazar Tal (Chitwan), le réservoir de Jagdishpur (Kapilvastu) et Ghodaghodi Tal (Kailali) dans le Teraï, ainsi que Gokyo (Solukhumbu), Phoksundo (Dolpa), Rara (Mugu) et Mai Pokhari (Ilam) dans la région montagneuse. Le pays compte plus de 30 grottes naturelles, dont seules quelques-unes sont accessibles par la route. La grotte de Maratika (aussi appelée Haleshi) est un lieu de pèlerinage associé au bouddhisme et à l\'hindouisme. La grotte de Siddha se trouve près de Bimalnagar, le long de la route Katmandou-Pokhara. Pokhara est également connue pour ses grottes, notamment l\'abri aux chauves-souris, Batulechar, Gupteswar et Patale Chhango. Les nombreuses grottes autour de Lo Manthang, au Mustang, comprennent Luri et Tashi Kabum, qui abritent d\'anciennes fresques et chörtens datant du XIIIe siècle.','Offer water stations, avoiding plastic bottles in-office.'=>'Proposer des fontaines à eau, en évitant les bouteilles plastique au bureau.','Office'=>'Bureau','Office hours 9:00 AM to 5:00 PM, Nepal time.'=>'Horaires du bureau : 9h00 à 17h00, heure du Népal.','On the 21 November 2005 a peace agreement between the Government of Nepal and the Maoists was signed, thereby ending a decade long conflict in Nepal. Both sides agreed to a permanent ceasefire.'=>'Le 21 novembre 2005, un accord de paix entre le gouvernement du Népal et les maoïstes fut signé, mettant fin à un conflit vieux d\'une décennie. Les deux parties acceptèrent un cessez-le-feu permanent.','On the ground with our guides'=>'Sur le terrain avec nos guides','On this page'=>'Sur cette page','Only the first is required for the site to work. The other three you can decline in your browser at any time.'=>'Seul le premier est nécessaire au fonctionnement du site. Vous pouvez refuser les trois autres à tout moment depuis votre navigateur.','Open navigation'=>'Ouvrir la navigation','Operate transparently and maintain <strong>financial integrity</strong>.'=>'Fonctionner en toute transparence et maintenir une <strong>intégrité financière</strong>.','Operate with transparency'=>'Fonctionner en toute transparence','Operations in Kathmandu'=>'Opérations à Katmandou','Operations on the trail'=>'Opérations sur le terrain','Optional'=>'Facultatif','Optional Items'=>'Éléments facultatifs','Other news'=>'Autres actualités','Others have shared theirs too, right here'=>'D\'autres ont aussi partagé leur avis, juste ici','Our blog or informational pages may include <strong>embedded content</strong> (videos, maps, articles, etc.).'=>'Notre blog ou nos pages d\'information peuvent inclure du <strong>contenu intégré</strong> (vidéos, cartes, articles, etc.).','Our commitment'=>'Notre engagement','Our commitment goes beyond tourism; we are dedicated to empowering local communities. By collaborating with local businesses, supporting artisans, and promoting fair trade practices, we aim to foster sustainable development in the regions we operate.'=>'Notre engagement va au-delà du tourisme ; nous nous attachons à donner les moyens d\'agir aux communautés locales. En collaborant avec les entreprises locales, en soutenant les artisans et en encourageant les pratiques de commerce équitable, nous visons à favoriser le développement durable dans les régions où nous sommes présents.','Our core values, how they are integrated across operations, and how we keep improving on them.'=>'Nos valeurs fondamentales, la façon dont elles sont intégrées à nos activités, et comment nous continuons à les améliorer.','Our guiding frameworks'=>'Nos cadres de référence','Our liability is <strong>limited to the cost of the tour purchased</strong>.'=>'Notre responsabilité est <strong>limitée au coût du voyage acheté</strong>.','Our site may contain <strong>embedded content</strong> — videos or social media buttons, for example — which may place its own cookies.'=>'Notre site peut contenir du <strong>contenu intégré</strong> — vidéos ou boutons de réseaux sociaux, par exemple — qui peut déposer ses propres cookies.','Our website address is %s.'=>'L\'adresse de notre site web est %s.','Our website may link to third-party sites (e.g. insurance providers, affiliate travel blogs).'=>'Notre site peut contenir des liens vers des sites tiers (assureurs, blogs de voyage partenaires, etc.).','Outerwear:'=>'Vêtements d\'extérieur :','Page %1$s of %2$s'=>'Page %1$s sur %2$s','Pages visited, time spent, and click activity.'=>'Pages visitées, temps passé et activité de clic.','Paperwork'=>'Formalités','Participation at your own risk'=>'Participation à vos propres risques','Partner & Supplier Sustainability Criteria'=>'Critères de durabilité pour partenaires et fournisseurs','Partner only with suppliers who adhere to fair trade and sustainability standards.'=>'Ne collaborer qu\'avec des fournisseurs respectant le commerce équitable et les normes de durabilité.','Partner with <strong>local farms</strong> and prefer organic, seasonal, and vegetarian options.'=>'Collaborez avec <strong>les exploitations agricoles locales</strong> et privilégiez les produits bio, de saison et végétariens.','Partners'=>'Partenaires','Passport photos (you’ll need these for trekking permits, buying a SIM card, and for your Cheers volunteer card).'=>'Photos d\'identité (nécessaires pour les permis de trek, l\'achat d\'une carte SIM et votre carte de bénévole Cheers).','Payment card'=>'Carte de paiement','Payment information'=>'Informations de paiement','Payment methods include bank transfer, major credit cards, or online gateways. Any associated <strong>transaction charges are borne by the client</strong>.'=>'Les moyens de paiement incluent le virement bancaire, les principales cartes de crédit ou les plateformes en ligne. Les <strong>frais de transaction associés sont à la charge du client</strong>.','Payments made through our site are securely processed by <strong>trusted third-party providers</strong>.'=>'Les paiements effectués via notre site sont traités en toute sécurité par des <strong>prestataires tiers de confiance</strong>.','People'=>'Personnes','People connecting within a local community'=>'Les personnes qui tissent des liens au sein d\'une communauté locale','People sharing time together in a local community'=>'Des personnes qui partagent des moments ensemble au sein d\'une communauté locale','People walking through Kathmandu Durbar Square'=>'Des passants sur la place Durbar de Katmandou','Personal and payment information'=>'Informations personnelles et de paiement','Personal information'=>'Informations personnelles','Phone'=>'Téléphone','Phone / WhatsApp'=>'Téléphone / WhatsApp','Place'=>'Lieu','Placements with local partners'=>'Stages auprès de partenaires locaux','Plan My Nepal Trip'=>'Planifier mon voyage au Népal','Plan Your Trip'=>'Planifiez votre voyage','Plastic-Free & Waste Management Guide'=>'Guide zéro plastique et gestion des déchets','Please contact us at %s for any data access or removal request.'=>'Veuillez nous contacter à %s pour toute demande d\'accès ou de suppression de données.','Please enter a valid email address.'=>'Veuillez saisir une adresse e-mail valide.','Please enter a valid mobile number.'=>'Veuillez saisir un numéro de mobile valide.','Please enter your full name.'=>'Veuillez saisir votre nom complet.','Please enter your question or message.'=>'Veuillez saisir votre question ou votre message.','Please read these before confirming your booking. They cover payment, cancellation, insurance, safety and how we resolve any issue.'=>'Veuillez les lire avant de confirmer votre réservation. Elles couvrent le paiement, l\'annulation, l\'assurance, la sécurité et notre gestion des litiges.','Please select your country.'=>'Veuillez sélectionner votre pays.','Policies in Practice'=>'Politiques en pratique','Policy'=>'Politique','Politically Nepal is continuing to undergo a period of change, and in light of this you should avoid large gatherings and demonstrations. Bandhas (shutdowns), rallies and demonstrations can cause widespread disruption as they are often called at short notice, and disrupt transport. However, in general CN volunteers are not impacted by these types of demonstrations, as their site of volunteering is in close proximity to their accommodation.'=>'Sur le plan politique, le Népal continue de traverser une période de changement ; il est donc conseillé d\'éviter les grands rassemblements et manifestations. Les bandhs (grèves générales), rassemblements et manifestations peuvent perturber largement le pays, étant souvent annoncés à court terme et perturbant les transports. Toutefois, les bénévoles ne sont généralement pas affectés par ce type de manifestations, leur lieu de mission étant proche de leur hébergement.','Politics'=>'Politique','Prakash, global representative in the USA'=>'Prakash, représentant mondial aux États-Unis','Prem, Chief Executive'=>'Prem, directeur général','Prepare for your appointment'=>'Préparez votre rendez-vous','Preserve heritage and respect the customs of every place we visit.'=>'Préserver le patrimoine et respecter les coutumes de chaque lieu visité.','Preserving Cultural Heritage:'=>'Préservation du patrimoine culturel :','Preserving Nepal&rsquo;s Natural Beauty:'=>'Préservation de la beauté naturelle du Népal :','Previous'=>'Précédent','Previous departures'=>'Départs précédents','Previous people'=>'Les personnes précédentes','Previous review'=>'Avis précédent','Price tag'=>'Étiquette de prix','Primary navigation'=>'Navigation principale','Print only when necessary and use <strong>FSC-certified or recycled paper</strong>.'=>'N\'imprimer qu\'en cas de nécessité et utiliser du <strong>papier certifié FSC ou recyclé</strong>.','Prioritise <strong>local guides, homestays, artisans</strong>, and transport providers.'=>'Privilégiez <strong>les guides locaux, les séjours chez l\'habitant, les artisans</strong> et les prestataires de transport.','Privacy %s'=>'%s de confidentialité','Privacy & Data Protection'=>'Confidentialité et protection des données','Privacy <span class="underline">Policy</span>'=>'<span class="underline">Politique</span> de confidentialité','Privacy Policy'=>'Politique de confidentialité','Private & small-group options'=>'Options privées et petits groupes','Process bookings and issue <strong>confirmations</strong>.'=>'Traiter les réservations et émettre des <strong>confirmations</strong>.','Promote <strong>low-impact travel</strong>, especially trekking, cycling, and nature tours.'=>'Promouvoir un <strong>tourisme à faible impact</strong>, notamment le trek, le vélo et les circuits nature.','Promote honesty, safety, and respect in all services delivered.'=>'Promouvoir l\'honnêteté, la sécurité et le respect dans tous nos services.','Promote social equity'=>'Promouvoir l\'équité sociale','Promote sustainable tourism advocacy in partnership with <strong>NGOs and networks</strong>.'=>'Promouvoir le tourisme durable en partenariat avec <strong>des ONG et des réseaux</strong>.','Promote the use of <strong>electric vehicles</strong> where possible.'=>'Promouvoir l\'utilisation de <strong>véhicules électriques</strong> lorsque possible.','Provide <strong>cultural briefings</strong> to travellers before tours.'=>'Fournir des <strong>briefings culturels</strong> aux voyageurs avant les circuits.','Provide regular training and capacity-building for our team.'=>'Assurer une formation régulière et le renforcement des compétences de notre équipe.','Provide reusable containers for packed meals and discourage single-use packaging.'=>'Fournir des contenants réutilisables pour les repas à emporter et décourager les emballages à usage unique.','Public Communication & Awareness'=>'Communication et sensibilisation du public','Purposes for processing'=>'Finalités du traitement','Rain (mm)'=>'Pluie (mm)','Raju, global representative in France'=>'Raju, représentant mondial en France','Ranging from the subtropical forests of the Terai to the great peaks of the Himalayas in the north, Nepal abounds with some of the most spectacular sceneries in the whole of Asia, with a variety of fauna and flora also unparalleled elsewhere in the region. Between Nepal&rsquo;s geographical extremes, one may find every vegetational type, from the treeless steppes of the Trans-Himalayan region in the extreme north and the birch, silver fir, larch and hemlock of the higher valleys to the oak, pine and rhododendron of the intermediate altitudes and the great sal and sissau forests of the south.'=>'Des forêts subtropicales du Teraï aux grands sommets de l\'Himalaya au nord, le Népal regorge de certains des paysages les plus spectaculaires de toute l\'Asie, avec une diversité de faune et de flore sans équivalent dans le reste de la région. Entre les extrêmes géographiques du Népal, on trouve tous les types de végétation, depuis les steppes dépourvues d’arbres de la région transhimalayenne à l’extrême nord, en passant par les bouleaux, les sapins argentés, les mélèzes et les pruches des hautes vallées, jusqu’aux chênes, pins et des rhododendrons des altitudes intermédiaires, jusqu’aux grandes forêts de sal et de sissau du sud.','Reach via head office'=>'Contacter le siège social','Read'=>'Lire','Read %s'=>'Lire %s','Read my'=>'Lire mes','Read the policy'=>'Lire la politique','Read the terms'=>'Lire les conditions','Read: %s'=>'Lecture : %s','reading'=>'lecture','Recent news'=>'Actualités récentes','Recommend <strong>filtered or boiled water</strong> over bottled water to travellers.'=>'Recommander aux voyageurs de l\'<strong>eau filtrée ou bouillie</strong> plutôt que de l\'eau en bouteille.','Recommended Items'=>'Éléments recommandés','Recommended on'=>'Recommandé sur','Records mention the Gopalas and Mahishapalas believed to have been the earliest rulers with their capital at Matatirtha, the south-west corner of the Kathmandu Valley. From the 7th or 8th Century B.C. the Kirantis are said to have ruled the valley. Their famous King Yalumber is even mentioned in the epic, &lsquo;Mahabharat&rsquo;. Around 300 A.D. the Lichhavis arrived from northern India and overthrew the Kirantis. One of the legacies of the Lichhavis is the Changu Narayan Temple near Bhaktapur, a UNESCO World Heritage Site (Culture), which dates back to the 5th Century. In the early 7th Century, Amshuvarma, the first Thakuri king took over the throne from his father-in-law who was a Lichhavi. He married off his daughter Bhrikuti to the famous Tibetan King Tsong Tsen Gampo thus establishing good relations with Tibet. The Lichhavis brought art and architecture to the valley but the golden age of creativity arrived in 1200 A.D with the Mallas.'=>'Les archives mentionnent les Gopala et les Mahishapala, considérés comme les premiers souverains, avec leur capitale à Matatirtha, à l\'angle sud-ouest de la vallée de Katmandou. Du VIIe ou VIIIe siècle av. J.-C., les Kirati auraient régné sur la vallée. Leur célèbre roi Yalambar est même mentionné dans l\'épopée du « Mahabharata ». Vers 300 apr. J.-C., les Licchavi arrivèrent du nord de l\'Inde et renversèrent les Kirati. L\'un des héritages des Licchavi est le temple de Changu Narayan, près de Bhaktapur, site du patrimoine mondial de l\'UNESCO (culture), qui remonte au Ve siècle. Au début du VIIe siècle, Amshuvarma, premier roi Thakuri, prit le trône de son beau-père, un Licchavi. Il maria sa fille Bhrikuti au célèbre roi tibétain Songtsen Gampo, établissant ainsi de bonnes relations avec le Tibet. Les Licchavi apportèrent l\'art et l\'architecture à la vallée, mais l\'âge d\'or de la création arriva en 1200 apr. J.-C. avec les Malla.','Recycle waste and use <strong>reusable containers</strong> and office supplies.'=>'Recycler les déchets et utiliser des <strong>contenants réutilisables</strong> et des fournitures de bureau durables.','Reduce greenhouse gas emissions and <strong>offset unavoidable carbon</strong>.'=>'Réduire les émissions de gaz à effet de serre et <strong>compenser le carbone incompressible</strong>.','Regardless of provision stated in 2(a), 15 days is counted as minimum extension period and visa fee is charged accordingly. For extension period more than 15 days, visa fee is charged as per the provision of 2(a).'=>'Indépendamment des dispositions énoncées au point 2(a), une période minimale de prolongation de 15 jours est comptabilisée et les frais de visa sont facturés en conséquence. Pour une prolongation supérieure à 15 jours, les frais sont facturés conformément aux dispositions du point 2(a).','Regardless of the provision stated in 1(a) and 1(b), tourists with passport from South Asian Association for Regional Cooperation (SAARC) nations aren’t required to pay visa fee for 30 days.'=>'Nonobstant les dispositions prévues aux paragraphes 1(a) et 1(b), les touristes titulaires d\'un passeport délivré par un pays membre de l\'Association sud-asiatique de coopération régionale (SAARC) sont dispensés de payer les frais de visa pour un séjour de 30 jours.','Regularly service vehicles for <strong>fuel efficiency and emission control</strong>.'=>'Entretenir régulièrement les véhicules pour une <strong>efficacité énergétique et un contrôle des émissions</strong> optimaux.','Regularly update policies based on staff input, client feedback, and industry innovations.'=>'Mettre régulièrement à jour nos politiques selon les retours du personnel, des clients et les innovations du secteur.','Remember your <strong>preferences</strong>.'=>'Mémoriser vos <strong>préférences</strong>.','Remember your preferences — such as language or region — to improve your experience.'=>'Mémoriser vos préférences — comme la langue ou la région — pour améliorer votre expérience.','Request a copy of the personal data we hold about you.'=>'Demander une copie des données personnelles que nous détenons à votre sujet.','Request deletion, except data we must retain for legal reasons.'=>'Demander la suppression, sauf pour les données que nous devons conserver pour des raisons légales.','Respect <strong>local cultures, customs and religious sites</strong>.'=>'Respectez <strong>les cultures locales, les coutumes et les lieux de culte</strong>.','Respect <strong>sacred sites, local customs, and dress codes</strong>.'=>'Respectez <strong>les lieux sacrés, les coutumes locales et les codes vestimentaires</strong>.','Respect on the ground'=>'Respect sur le terrain','Respect the privacy and data of all customers and staff — see our %s.'=>'Respecter la vie privée et les données de tous les clients et employés — voir notre %s.','Respond to enquiries and offer customer support.'=>'Répondre aux demandes et offrir un support client.','Retention periods'=>'Durées de conservation','Retreats in Nepal'=>'Retraites au Népal','Risk Acknowledgment & Liability'=>'Reconnaissance des risques et responsabilité','Roll momos with a local chef, learn traditional Thangka painting, try your hand at wood carving, or join in a vibrant local festival. These moments often become the most cherished parts of the journey.'=>'Préparez des momos avec un chef local, initiez-vous à la peinture traditionnelle de thangkas, essayez-vous à la sculpture sur bois ou participez à un festival local haut en couleur. Ces moments deviennent souvent les plus chers à votre cœur tout au long du voyage.','Run the final submission check'=>'Effectuer la vérification finale avant soumission','Safari'=>'Safari','Safari Tours'=>'Circuits safari','Safety'=>'Sécurité','Safety & Emergency Procedures'=>'Sécurité et procédures d\'urgence','Safety and security.'=>'Sécurité et sûreté.','Safety First, Ethical Practices'=>'La sécurité d\'abord, des pratiques éthiques','Schengen'=>'Schengen','Search'=>'Rechercher','Search articles'=>'Rechercher des articles','Search blogs'=>'Rechercher des blogs','search headlineYou'=>'Vous','Search news'=>'Rechercher des actualités','Search news…'=>'Rechercher des actualités…','Search treks, retreats…'=>'Rechercher des treks, retraites…','Sections on this page'=>'Sections de cette page','See all the news'=>'Voir toutes les actualités','See our full %s for details.'=>'Consultez notre %s complète pour plus de détails.','Select your country'=>'Sélectionnez votre pays','Send a message'=>'Envoyer un message','Send newsletters, updates, and promotional content &mdash; <strong>only with your consent</strong>.'=>'Envoyer des newsletters, mises à jour et contenus promotionnels &mdash; <strong>uniquement avec votre consentement</strong>.','Send us a message'=>'Envoyez-nous un message','Share our <strong>sustainability progress</strong> on our website and social media.'=>'Partager nos <strong>avancées en matière de durabilité</strong> sur notre site et nos réseaux sociaux.','Share this article'=>'Partager cet article','Share this news'=>'Partager cette actualité','Sharing what we learn'=>'Partager ce que nous apprenons','Shield'=>'Bouclier','Significant changes will be communicated via <strong>email or site notification</strong>.'=>'Les changements importants seront communiqués par <strong>e-mail ou notification sur le site</strong>.','Site footer'=>'Pied de page du site','Sites we link out to'=>'Sites vers lesquels nous créons des liens','Six promises we <span class="underline">hold ourselves to</span>'=>'Six engagements que <span class="underline">nous nous imposons</span>','Skip to content'=>'Aller directement au contenu','Sleeping Bag / Sleeping Bag Liner:'=>'Sac de couchage / doublure de sac de couchage :','South Korea'=>'Corée du Sud','Spam checks and trip operations'=>'Contrôles anti-spam et gestion des voyages','Spare lenses and enough solution.'=>'Lentilles de rechange et suffisamment de solution.','Speak with a representative'=>'Parlez à un représentant','Speak with our worldwide <span class="accent">representative</span>'=>'Parlez à notre <span class="accent">représentant</span> mondial','Sponsor and invitation document review'=>'Vérification des documents de parrainage et d\'invitation','Spouse &amp; Partner Visa'=>'Visa conjoint et partenaire','Standard'=>'Standard','Start planning'=>'Commencez à planifier','Still have a question? Ask the Kathmandu team'=>'Encore une question ? Demandez à l\'équipe de Katmandou','Stored indefinitely'=>'Conservées indéfiniment','Students learning together in a classroom'=>'Des élèves apprenant ensemble dans une salle de classe','Subalpine and Alpine Zone'=>'Zone subalpine et alpine','Submission and follow-up guidance'=>'Accompagnement pour le dépôt et le suivi','Submit'=>'Envoyer','Subtropical Mixed Evergreen Forest'=>'Forêt subtropicale mixte à feuilles persistantes','Summer (May, June, July)'=>'Été (mai, juin, juillet)','Sun cream'=>'Crème solaire','Sun Protection:'=>'Protection solaire :','Sunglasses'=>'Lunettes de soleil','Support <strong>local businesses and artisans</strong>.'=>'Soutenez <strong>les entreprises locales et les artisans</strong>.','Support biodiversity conservation and <strong>avoid wildlife exploitation</strong>.'=>'Soutenir la conservation de la biodiversité et <strong>éviter l\'exploitation de la faune</strong>.','Support from arrival to departure'=>'Accompagnement de l\'arrivée au départ','Suraj, global representative in Australia'=>'Suraj, représentant mondial en Australie','Sustainability %s'=>'%s de durabilité','Sustainability <span class="underline">Policy</span>'=>'<span class="underline">Politique</span> de durabilité','Sustainability Coordinator'=>'Coordinateur de durabilité','Sustainability is a <strong>standing agenda item</strong> in all management meetings.'=>'La durabilité est un <strong>point permanent à l\'ordre du jour</strong> de toutes les réunions de direction.','Sustainability is not just an environmental concern — it is an integrated approach involving ethical business, community empowerment, cultural respect and climate-conscious travel.'=>'La durabilité n\'est pas qu\'une préoccupation environnementale — c\'est une approche intégrée combinant éthique commerciale, autonomisation des communautés, respect culturel et voyage responsable face au climat.','Sustainability Policy'=>'Politique de durabilité','Sustainable & Ethical Travel'=>'Voyage durable et éthique','Sustainable & Inclusive Travel'=>'Voyage durable et inclusif','Sustainable Accommodation Standards'=>'Normes d\'hébergement durable','Sustainable Excursions & Code of Conduct'=>'Excursions durables et code de conduite','Sustainable Procurement Policy'=>'Politique d\'achats durables','Sustainable travel pledge'=>'Engagement pour un voyage durable','Tailored Tours &amp; Cultural Journeys'=>'Circuits sur mesure et voyages culturels','Talk to a Kathmandu-based expert and shape a trek, tour or retreat around how you want to travel.'=>'Parlez à un expert basé à Katmandou et concevez un trek, un circuit ou une retraite selon la façon dont vous voulez voyager.','Talk to a Kathmandu-based expert and shape a trek, tour, retreat or volunteer placement around you.'=>'Parlez à un expert basé à Katmandou et façonnez un trek, un circuit, une retraite ou une mission de bénévolat autour de vous.','Talk to our team'=>'Parlez à notre équipe','Tarkeshwor-2, Kathmandu'=>'Tarkeshwor-2, Katmandou','Tarkeshwor-2,<br>KATHMANDU, NEPAL'=>'Tarkeshwor-2,<br>KATMANDOU, NÉPAL','Tarkeshwor-2,<br>Kathmandu, Nepal'=>'Tarkeshwor-2,<br>Katmandou, Népal','Team'=>'Équipe','Tell us how you want to travel'=>'Dites-nous comment vous voulez voyager','Tell us where you are, how to reach you, and what you would like to know.'=>'Dites-nous où vous êtes, comment vous joindre, et ce que vous souhaitez savoir.','Temperate Evergreen Forest'=>'Forêt tempérée à feuilles persistantes','Terai People'=>'Les habitants du Teraï','Terms & %s'=>'Conditions & %s','Terms & Conditions'=>'Conditions générales','Terms &amp; <span class="underline">Conditions</span>'=>'<span class="underline">Conditions</span> générales','Thailand'=>'Thaïlande','The basics'=>'L\'essentiel','The company behind this website'=>'L\'entreprise derrière ce site','The Himalaya beneath a clear Nepal sky'=>'L\'Himalaya sous un ciel népalais dégagé','The Himalayas (above 3,000 m) comprises mountains, alpine pastures and temperate forests limited by the tree-line (4,000 m) and snow line (5,500 m). Eight of the 14 eight-thousanders of the world lie in Nepal: Sagarmatha or Mount Everest (8,848 m), Kanchenjunga (8,586 m), Lhotse (8,516 m), Makalu (8,463 m), Cho Oyu (8,201m), Dhaulagiri (8,167 m), Manaslu (8,163 m) and Annapurna (8,091 m). The inner Himalayan valley (above 3,600 m) such as Mustang and Dolpa are cold deserts sharing topographical characteristics with the Tibetan plateau. Nepal holds the so called &ldquo;waters towers of South Asia&rdquo; with its 6,000 rivers which are snow-fed or dependent on rain. The perennial rivers include Mahakali, Karnali, Narayani and Koshi rivers originating in the Himalayas. Medium-sized rivers like Babai, West Rapti, Bagmati, Kamla, Kankai and Mechi originate in the Midlands and Mahabharat range. A large number of seasonal streams, mostly originating in Siwaliks, flow across the Terai.'=>'L\'Himalaya (au-dessus de 3 000 m) comprend montagnes, pâturages alpins et forêts tempérées, limités par la limite forestière (4 000 m) et la limite des neiges (5 500 m). Huit des 14 sommets de plus de 8 000 m du monde se trouvent au Népal : le Sagarmatha ou mont Everest (8 848 m), le Kangchenjunga (8 586 m), le Lhotse (8 516 m), le Makalu (8 463 m), le Cho Oyu (8 201 m), le Dhaulagiri (8 167 m), le Manaslu (8 163 m) et l\'Annapurna (8 091 m). Les vallées himalayennes intérieures (au-dessus de 3 600 m), comme le Mustang et le Dolpa, sont des déserts froids partageant des caractéristiques topographiques avec le plateau tibétain. Le Népal détient ce qu\'on appelle le « château d\'eau de l\'Asie du Sud » avec ses 6 000 rivières, alimentées par la fonte des neiges ou les pluies. Les rivières pérennes comprennent la Mahakali, la Karnali, la Narayani et la Koshi, prenant leur source dans l\'Himalaya. Des rivières de taille moyenne comme la Babai, la West Rapti, la Bagmati, la Kamla, la Kankai et la Mechi prennent leur source dans les Midlands et la chaîne du Mahabharat. De nombreux cours d\'eau saisonniers, majoritairement issus des Siwaliks, traversent le Teraï.','The history of the Gorkha state goes back to 1559 when Dravya Shah established a kingdom in an area chiefly inhabited by Magars. During the 17th and early 18th centuries, Gorkha continued a slow expansion, conquering various states while forging alliances with others. Prithvi Narayan dedicated himself at an early age to the conquest of the Kathmandu Valley. Recognizing the threat of the British Raj in India, he dismissed European missionaries from the country and for more than a century, Nepal remained in isolation.'=>'L\'histoire de l\'État de Gorkha remonte à 1559, lorsque Dravya Shah fonda un royaume dans une région principalement peuplée de Magars. Au cours du XVIIe siècle et au début du XVIIIe, Gorkha poursuivit une lente expansion, conquérant divers États tout en nouant des alliances avec d\'autres. Prithvi Narayan se consacra dès son plus jeune âge à la conquête de la vallée de Katmandou. Conscient de la menace que représentait le Raj britannique en Inde, il expulsa les missionnaires européens du pays et, pendant plus d’un siècle, le Népal resta isolé.','The latest trip news and announcements from our team in Kathmandu.'=>'Les dernières actualités et annonces de voyage de notre équipe à Katmandou.','The lowest is Kechana Kalan in Jhapa, at 60 m &mdash; the two ends of the country sit 8,788 metres apart.'=>'Le point le plus bas est Kechana Kalan, à Jhapa, à 60 m &mdash; les deux extrémités du pays sont séparées de 8 788 mètres.','The Maoist-led coalition government took office in September 2008, but in May 2009 the Prime Minister announced his resignation, increasing political uncertainty.'=>'Le gouvernement de coalition dirigé par les maoïstes prit ses fonctions en septembre 2008, mais en mai 2009, le Premier ministre annonça sa démission, accentuant l\'incertitude politique.','The policy in full'=>'La politique dans son intégralité','The population of Nepal was recorded to be about 26.62 million according to a recent survey done by the Central Bureau of Statistics, Nepal. The population comprises of about a 101 ethnic groups speaking over 92 languages. The distinction in caste and ethnicity is understood more easily with a view of customary layout of the population. Though, there exist numerous dialects, the language of unification is the national language, Nepali. Nepali is the official language of the state, spoken and understood by majority of the population. Multiple ethnic groups have their own mother tongues. English is spoken by many in Government and business offices. It is the mode of education in most private schools of Kathmandu and some other cities.'=>'La population du Népal était estimée à environ 26,62 millions d\'habitants selon une enquête récente du Bureau central des statistiques du Népal. La population compte environ 101 groupes ethniques parlant plus de 92 langues. La distinction de caste et d\'ethnie se comprend plus facilement au regard de la répartition traditionnelle de la population. Bien qu\'il existe de nombreux dialectes, la langue d\'unification est la langue nationale, le népalais. Le népalais est la langue officielle de l\'État, parlée et comprise par la majorité de la population. De nombreux groupes ethniques ont leur propre langue maternelle. L\'anglais est parlé par beaucoup dans les administrations et bureaux d\'affaires. C\'est la langue d\'enseignement dans la plupart des écoles privées de Katmandou et de certaines autres villes.','The right season depends on what you want to do. Autumn and spring are popular for trekking, while cultural trips, wildlife experiences and retreats can work well across a broader part of the year.'=>'Le choix de la saison dépend de ce que vous souhaitez faire. L\'automne et le printemps sont des périodes très prisées pour la randonnée, tandis que les séjours culturels, les découvertes de la faune sauvage et les retraites peuvent se pratiquer sur une plus grande partie de l\'année.','The rolling densely forested hills and broad Dun valleys of the Terai along with other parts of the country, were formerly, renowned for their abundance and variety o wildlife. Though somewhat depleted as a result of agricultural settlements, deforestation, poaching and other causes, Nepal can still boast richer and more varied flora and fauna than any other area in Asia. For practical purposes, Nepal&rsquo;s flora and fauna can be divided into four regions:-'=>'Les collines vallonnées et densément boisées ainsi que les larges vallées (Duns) du Teraï, comme d\'autres parties du pays, étaient autrefois réputées pour l\'abondance et la diversité de leur faune. Bien que quelque peu appauvrie par l\'installation agricole, la déforestation, le braconnage et d\'autres causes, le Népal peut encore se targuer d\'une flore et d\'une faune plus riches et plus variées que n\'importe quelle autre région d\'Asie. En pratique, la flore et la faune du Népal peuvent être divisées en quatre régions :','The stories our trip planners are fielding the most questions about right now.'=>'Les sujets sur lesquels nos organisateurs de voyages reçoivent le plus de questions en ce moment.','The Terai region, with width of ranging 26 to 32 km and altitude ranging from 60 -305 m, occupies about 17 percent of total land area of the country. Kechana Kalan, the lowest point of the country with an altitude of 60 m, lies in Jhapa district of the eastern Terai. The southern lowland Terai continues to the Bhabar belt covered with the Char Kose Jhadi forests known for rich wildlife. Further north, the Siwalik zone (700 &ndash; 1,500 m) and the Mahabharat range (1,500 &ndash; 2,700 m) give way to the Duns (valleys), such as Trijuga, Sindhuli, Chitwan, Dang and Surkhet. The Midlands (600 &ndash; 3,500 m), north of the Mahabharat range is where the two beautiful valleys of Kathmandu and Pokhara lie covered in terraced rice fields, and surrounded by forested watersheds.'=>'La région du Teraï, large de 26 à 32 km et d\'une altitude comprise entre 60 et 305 m, occupe environ 17 % de la superficie totale du pays. Kechana Kalan, le point le plus bas du pays à 60 m d\'altitude, se trouve dans le district de Jhapa, dans le Teraï oriental. Le Teraï méridional se prolonge par la ceinture du Bhabar, couverte des forêts de Char Kose Jhadi, réputées pour leur riche faune. Plus au nord, la zone des Siwaliks (700 à 1 500 m) et la chaîne du Mahabharat (1 500 à 2 700 m) cèdent la place aux Duns (vallées), telles que Trijuga, Sindhuli, Chitwan, Dang et Surkhet. Les Midlands (600 à 3 500 m), au nord de la chaîne du Mahabharat, abritent les deux magnifiques vallées de Katmandou et Pokhara, couvertes de rizières en terrasses et entourées de bassins versants boisés.','The tourist visa shall be granted for a period in maximum of 150 days in a visa year (Visa years means January to December).'=>'Le visa touristique sera accordé pour une durée maximale de 150 jours par année de visa (l\'année de visa s\'entendant de janvier à décembre).','There is no seasonal constraint on traveling in and through Nepal. Even in December and January, when winter is at its severest, there are compensating bright sun and brilliant views. As with most of the trekking areas in Nepal, the best time to visit are during spring and autumn. Spring is the time for rhododendrons while the clearest skies are found after the monsoon in October and November. However, Nepal can be visited the whole year round. Average temperatures and rainfall during peak summer and winter in three most popular tourist areas:'=>'Il n\'existe aucune contrainte saisonnière pour voyager au Népal. Même en décembre et janvier, au plus fort de l\'hiver, un soleil éclatant et des vues splendides compensent le froid. Comme pour la plupart des zones de trek du Népal, la meilleure période pour visiter est le printemps et l\'automne. Le printemps est la saison des rhododendrons, tandis que les ciels les plus dégagés s\'observent après la mousson, en octobre et novembre. Le Népal peut néanmoins se visiter toute l\'année. Températures et précipitations moyennes en plein été et en plein hiver dans les trois zones touristiques les plus populaires :','These behave as if you visited the other website, which <strong>may collect data, use cookies, or track your interaction</strong>.'=>'Ceux-ci se comportent comme si vous aviez visité l\'autre site, qui <strong>peut collecter des données, utiliser des cookies ou suivre votre interaction</strong>.','Third-Party Cookies'=>'Cookies tiers','Third-Party Links'=>'Liens vers des tiers','This includes the Mahabharat Lekh, which rises to a height of about 2400m and comprises the outer wall of the Himalayan range. Great rivers such as the Karnali, Narayani, and Sapta Koshi flow through this area into the broad plains of the Terai. This zone also includes the so-called &lsquo;middle hills&rsquo; which extend northwards in a somewhat confused maze of ridges and valleys to the foot of the great Himalayas. Among the tree species characteristic of this region are Castenopsis indica in association with Schima wallichii, and other species such as Alnus nepalensis, Acer oblongum and various species of oak and rhododendron which cover the higher slopes where deforestation has not yet taken place. Orchids clothe the stems of trees and gigantic climbers smother their heads. The variety and abundance of the flora and fauna increase progressively with decreasing altitude and increasing luxurance of the vegetation. This zone is generally poor in wildlife. The only mammals, which are at all widely distributed, are wild boar, barking deer, serow, ghoral and bears. Different varieties of birds are also found in this zone.'=>'On y trouve notamment le Mahabharat Lekh, qui culmine à environ 2 400 m d’altitude et constitue la bordure extérieure de la chaîne himalayenne. De grands fleuves tels que le Karnali, le Narayani et le Sapta Koshi traversent cette région pour se jeter dans les vastes plaines du Teraï. Cette zone comprend également ce que l’on appelle les « collines intermédiaires », qui s’étendent vers le nord en un dédale quelque peu confus de crêtes et de vallées jusqu’au pied de l’Himalaya. Parmi les espèces d’arbres caractéristiques de cette région, on trouve le Castenopsis indica, associé au Schima wallichii, ainsi que d’autres espèces telles que l’Alnus nepalensis, l’Acer oblongum et diverses espèces de chênes et de rhododendrons qui recouvrent les pentes les plus élevées où la déforestation n’a pas encore eu lieu. Des orchidées tapissent les troncs des arbres et des lianes gigantesques en recouvrent la cime. La diversité et l’abondance de la flore et de la faune augmentent progressivement à mesure que l’altitude diminue et que la végétation devient plus luxuriante. Cette zone est généralement pauvre en faune sauvage. Les seuls mammifères présents en nombre suffisant sont le sanglier, le cerf aboyeur, le serow, le ghoral et l’ours. On trouve également différentes espèces d’oiseaux dans cette zone.','This includes the Terai plains and the broad flat valleys or Duns found between successive hill ranges. The dominant tree species of this area are Sal (Shorea Robusta), sometimes associated with Semal (Bombax malabricum), Asna (Terminalia termentosa), Dalbergia spp and other species, and Pinus rosburghi occurring on the higher ridges of the Churia hills, which in places reach an altitude of 1800m. Tall coarse two-meter high elephant grass originally covered much of the Dun valleys but has now been largely replaced by agricultural settlements. The pipal (ficus religiosa) and the &lsquo;banyan&rsquo; (ficus bengalensis) are to be noticed with their specific natural characteristics. This tropical zone is Nepal&rsquo;s richest area for wildlife, with gaurs, buffaloes, four species of deer, tigers, leopards and other animals found in the forest areas rhinoceros, swamp deer and hot deer found in the valley grasslands and two species of crocodile and the Gangetic dolphin inhabiting the rivers. The principal birds are the peacock, jungle fowl and black partridge, while migratory duck and geese swarm on the ponds and lakes and big rivers of Terai. Terai forests are full of jasmin, minosa, accecia reeds and bamboo.'=>'Cette zone comprend les plaines du Teraï et les larges vallées plates (Duns) situées entre les chaînes de collines successives. Les espèces d\'arbres dominantes sont le Sal (Shorea robusta), parfois associé au Semal (Bombax malabaricum), à l\'Asna (Terminalia tomentosa), aux Dalbergia spp et à d\'autres espèces, ainsi que le Pinus roxburghii sur les crêtes plus élevées des collines de Churia, atteignant par endroits 1 800 m d\'altitude. De hautes herbes à éléphants, épaisses et pouvant atteindre deux mètres, couvraient autrefois une grande partie des vallées Dun, aujourd\'hui largement remplacées par des zones agricoles. Le pipal (Ficus religiosa) et le banian (Ficus bengalensis) se distinguent par leurs caractéristiques naturelles propres. Cette zone tropicale est la plus riche du Népal en faune : gaurs, buffles, quatre espèces de cerfs, tigres, léopards et autres animaux dans les zones forestières ; rhinocéros, cerfs des marais et cerfs axis dans les prairies de la vallée ; ainsi que deux espèces de crocodiles et le dauphin du Gange dans les rivières. Les principaux oiseaux comprennent le paon, la poule sauvage et la perdrix noire, tandis que canards et oies migrateurs affluent sur les étangs, lacs et grandes rivières du Teraï. Les forêts du Teraï abondent en jasmin, mimosa, roseaux d\'acacia et bambous.','This will vary depending on the time of year in which you visit Nepal and what additional activities you intend to participate in during your stay in Nepal. With the exception of some medicines and high-tech trekking gear, you can buy everything that you would need for your placement in Kathmandu (and it is likely to be cheaper than in your home country). Here are a few suggestions on what to bring:'=>'Cela variera selon la période de l\'année où vous visitez le Népal et les activités supplémentaires auxquelles vous comptez participer durant votre séjour. À l\'exception de certains médicaments et du matériel de trek high-tech, vous pouvez acheter tout ce dont vous avez besoin pour votre mission à Katmandou (probablement moins cher que dans votre pays d\'origine). Voici quelques suggestions de ce qu\'il faut emporter :','Thumbs up'=>'Pouce levé','Tick'=>'Coche','Time: 9:00 AM to 5:00 PM'=>'Horaires : 9h00 à 17h00','Tools like Google Analytics show us how visitors use the site. These cookies are anonymous and help us improve performance.'=>'Des outils comme Google Analytics nous montrent comment les visiteurs utilisent le site. Ces cookies sont anonymes et nous aident à améliorer les performances.','Top news'=>'Actualités à la une','Torch / Flashlight:'=>'Lampe torche :','Tourism'=>'Tourisme','Tourism is a powerful tool for creating employment opportunities. We prioritize working with local guides, accommodation providers, and businesses, contributing to the economic growth of the areas we serve.'=>'Le tourisme est un outil puissant pour créer des opportunités d\'emploi. Nous privilégions la collaboration avec les guides locaux, les prestataires d\'hébergement et les entreprises locales, contribuant ainsi à la croissance économique des régions où nous sommes présents.','Tourist &amp; Visit Visa'=>'Visa touristique et de visite','Tourist visa'=>'Visa touristique','Trade'=>'Commerce','Transparent pricing with no hidden costs, so what you agree to is what you pay.'=>'Tarification transparente sans frais cachés : ce que vous acceptez est ce que vous payez.','Transportation'=>'Transport','Transportation & Carbon Offset Plan'=>'Plan de transport et de compensation carbone','Travel & adventure'=>'Voyage & aventure','Travel Expert'=>'Expert voyage','Travel Insurance'=>'Assurance voyage','Travel insurance is <strong>mandatory</strong> for all trekking, adventure and high-altitude trips.'=>'L\'assurance voyage est <strong>obligatoire</strong> pour tous les voyages de trek, d\'aventure et en haute altitude.','Travel itinerary review and preparation'=>'Vérification et préparation de l\'itinéraire de voyage','Travel preferences and <strong>health-related information</strong> (when necessary).'=>'Préférences de voyage et <strong>informations médicales</strong> (si nécessaire).','Travel Services &amp; Logistics'=>'Services de voyage et logistique','Traveller proof'=>'Preuve du voyageur','Traveller testimonials, use the left and right arrow keys'=>'Témoignages de voyageurs, utilisez les flèches gauche et droite','Travellers are expected to behave ethically, respectfully, and within the bounds of their assigned role.'=>'Les voyageurs sont tenus de se comporter de manière éthique, respectueuse et conforme au rôle qui leur est attribué.','Travellers must follow guide instructions and safety guidelines during the trip.'=>'Les voyageurs doivent suivre les instructions du guide et les consignes de sécurité pendant le voyage.','Travelling with us means agreeing to uphold this policy — see the sustainability clause in our %s.'=>'Voyager avec nous implique d\'accepter de respecter cette politique — voir la clause de durabilité dans notre %s.','Trek the Himalayas, discover heritage cities, meet local communities and explore Nepal\'s wildlife, landscapes and culture.'=>'Partez en randonnée dans l\'Himalaya, découvrez des villes chargées d\'histoire, rencontrez les populations locales et explorez la faune, les paysages et la culture du Népal.','Trekkers on a Himalayan trail in Nepal'=>'Trekkeurs sur un sentier himalayen au Népal','Trekkers planning to travel to controlled areas in Nepal opened for group trekking need to get Trekking Permit issued by the Department of Immigration under the Home Ministry. The government has opened following previously restricted trekking areas for group trekkers. Trekking permits will not be issued to individual trekkers in those trekking areas.'=>'Les trekkeurs prévoyant de se rendre dans des zones contrôlées du Népal ouvertes au trek en groupe doivent obtenir un permis de trek délivré par le département de l\'Immigration relevant du ministère de l\'Intérieur. Le gouvernement a ouvert au trek en groupe des zones auparavant restreintes. Les permis de trek individuels ne seront pas délivrés pour ces zones.','Trekking &amp; Adventure Travel'=>'Trek et voyage d\'aventure','Trekking in Nepal'=>'Trek au Népal','Trekking Permit'=>'Permis de trek','Trips planned to respect local communities, culture and the environment they pass through.'=>'Des circuits conçus dans le respect des communautés locales, de la culture et de l\'environnement qu\'ils traversent.','Tropical Deciduous Monsoon Forest'=>'Forêt tropicale de mousson à feuilles caduques','Turn off ambient sound'=>'Désactiver le son ambiant','Turn on ambient sound'=>'Activer le son ambiant','Turning cookies off'=>'Désactiver les cookies','Types of cookies'=>'Types de cookies','Types of Cookies We Use'=>'Types de cookies que nous utilisons','Types of cookies we use'=>'Types de cookies que nous utilisons','UAE'=>'Émirats arabes unis','UK'=>'Royaume-Uni','United Kingdom'=>'Royaume-Uni','United States'=>'États-Unis','Updates to this Policy'=>'Mises à jour de cette politique','Uphold fair labour and human rights'=>'Respecter le droit du travail équitable et les droits humains','Upload and submission assistance'=>'Assistance au téléversement et à la soumission','Upload or submit your application'=>'Téléversez ou soumettez votre demande','US $ 100 or equivalent foreign currency for Tourist Visa with Multiple Entry for 100 days.'=>'100 USD ou équivalent en devise étrangère pour un visa touristique à entrées multiples de 100 jours.','US $ 25 or equivalent foreign currency for Tourist Visa with Multiple Entry for 15 days.'=>'25 USD ou équivalent en devise étrangère pour un visa touristique à entrées multiples de 15 jours.','US $ 40 or equivalent foreign currency for Tourist Visa with Multiple Entry for 30 days.'=>'40 USD ou équivalent en devise étrangère pour un visa touristique à entrées multiples de 30 jours.','USA'=>'États-Unis','Use <strong>LED lighting</strong>, minimise power use, and follow a “switch off” protocol.'=>'Utilisez <strong>un éclairage LED</strong>, réduisez au minimum votre consommation d\'électricité et respectez une procédure d\'« extinction ».','Value for Money'=>'Bon rapport qualité-prix','Vehicles, flights and offsets'=>'Véhicules, vols et compensations','Vetted operators, briefed guides and clear protocols on every trip we run.'=>'Opérateurs vérifiés, guides briefés et protocoles clairs pour chaque voyage que nous organisons.','Videos, maps and articles'=>'Vidéos, cartes et articles','View'=>'Voir','View all %s'=>'Voir tout : %s','View all %s packages'=>'Voir tous les forfaits %s','View all articles'=>'Voir tous les articles','View all blogs'=>'Voir tous les blogs','View all news'=>'Voir toutes les actualités','View all packages'=>'Voir tous les forfaits','Vijay, global representative in Italy'=>'Vijay, représentant mondial en Italie','Visa & Entry Requirements'=>'Visa et conditions d\'entrée','Visa & permits'=>'Visa et permis','Visa application and form filling'=>'Demande de visa et remplissage du formulaire','Visa Appointment'=>'Rendez-vous visa','Visa Counseling'=>'Conseil en matière de visa','Visa Fee'=>'Frais de visa','Visa Services'=>'Services de visa','Visa, Permits and Fees'=>'Visa, permis et frais','Visitor comments may be checked through an <strong>automated spam detection service</strong>.'=>'Les commentaires des visiteurs peuvent être vérifiés via un <strong>service automatisé de détection des spams</strong>.','Volunteering & Community Programs'=>'Programmes de bénévolat et communautaires','Volunteering &amp; Community Engagement'=>'Bénévolat et engagement communautaire','Volunteering placements are run in collaboration with <strong>vetted local organisations</strong>.'=>'Les missions de bénévolat sont organisées en collaboration avec <strong>des associations locales agréées</strong>.','Volunteers should also avoid travel on overnight buses in Nepal.'=>'Les bénévoles doivent également éviter les trajets en bus de nuit au Népal.','Volunteers working together to support a community'=>'Des bénévoles travaillant ensemble pour soutenir une communauté','Water purification tablets and/or high-quality water purifier'=>'Pastilles de purification d\'eau et/ou purificateur d\'eau de haute qualité','Water Purification:'=>'Purification de l\'eau :','Waterproof jacket (a lightweight fold-away jacket is fine)'=>'Veste imperméable (une veste légère et pliable convient)','We <strong>do not control these cookies</strong>. Please refer to the policies of the sites they come from.'=>'Nous <strong>ne contrôlons pas ces cookies</strong>. Veuillez consulter les politiques des sites dont ils proviennent.','We <strong>do not sell your data</strong>. We may share information with:'=>'Nous <strong>ne vendons pas vos données</strong>. Nous pouvons les partager avec :','We <strong>do not store</strong> your credit card or sensitive payment information.'=>'Nous <strong>ne conservons pas</strong> vos données de carte bancaire ou informations de paiement sensibles.','We actively participate in initiatives that aim to preserve the breathtaking landscapes and biodiversity that make Nepal a haven for travelers. From supporting local conservation projects to promoting eco-friendly practices, we strive to minimize our ecological footprint.'=>'Nous participons activement à des initiatives visant à préserver les paysages à couper le souffle et la biodiversité qui font du Népal un véritable paradis pour les voyageurs. Qu\'il s\'agisse de soutenir des projets locaux de préservation de l\'environnement ou de promouvoir des pratiques respectueuses de l\'environnement, nous nous efforçons de réduire au maximum notre empreinte écologique.','We also collect your <strong>IP address and browser user agent string</strong> to help detect spam.'=>'Nous collectons également votre <strong>adresse IP et la chaîne d\'agent utilisateur de votre navigateur</strong> pour aider à détecter les spams.','We are <strong>not responsible for the privacy practices</strong> of these websites.'=>'Nous ne sommes <strong>pas responsables des pratiques de confidentialité</strong> de ces sites.','We are a leading <strong>travel and adventure agency in Nepal</strong>, offering trekking, cultural tours, retreats, workshops, volunteering, wildlife safaris, and multi-country experiences.'=>'Nous sommes une <strong>agence de voyage et d\'aventure de premier plan au Népal</strong>, proposant trek, circuits culturels, retraites, ateliers, bénévolat, safaris et expériences multi-pays.','We are dedicated to disaster relief, swiftly responding to crises with essential supplies, medical aid, and long-term reconstruction efforts. Our focus on community resilience includes training, healthcare, and infrastructure development.'=>'Nous nous consacrons à l\'aide aux sinistrés, en répondant rapidement aux crises par des fournitures essentielles, une aide médicale et des efforts de reconstruction à long terme. Notre engagement pour la résilience communautaire comprend la formation, la santé et le développement des infrastructures.','We are dedicated to improving the health and well-being of communities in need. From organizing health camps to supporting healthcare infrastructure, we actively engage in projects that address the unique healthcare challenges faced by different communities.'=>'Nous nous consacrons à l\'amélioration de la santé et du bien-être des communautés dans le besoin. De l\'organisation de camps de santé au soutien des infrastructures sanitaires, nous nous engageons activement dans des projets répondant aux défis de santé propres à chaque communauté.','We believe in the power of education to create lasting change. Through our projects, we contribute to educational initiatives that ensure children in remote areas have access to quality education, paving the way for a brighter future.'=>'Nous croyons au pouvoir de l\'éducation pour créer un changement durable. À travers nos projets, nous contribuons à des initiatives éducatives garantissant aux enfants des régions reculées l\'accès à une éducation de qualité, ouvrant la voie à un avenir meilleur.','We check every paper in your file on its own: bank statements, sponsor letters, travel history. If something looks weak or inconsistent, we tell you before the embassy does.'=>'Nous examinons un par un tous les documents contenus dans votre dossier : relevés bancaires, lettres de parrainage, historique de vos voyages. Si un élément nous semble peu convaincant ou incohérent, nous vous en informons avant même que l\'ambassade ne le fasse.','We collect only <strong>essential personal information</strong> to process bookings and deliver services.'=>'Nous ne collectons que les <strong>informations personnelles essentielles</strong> pour traiter les réservations et fournir nos services.','We collect the data shown in the <strong>comment form</strong>.'=>'Nous collectons les données indiquées dans le <strong>formulaire de commentaire</strong>.','We complete your visa application or form together, matching every field to your passport and supporting documents.'=>'Nous remplissons ensemble votre demande de visa, en faisant correspondre chaque champ à votre passeport et à vos documents justificatifs.','We design travel experiences that reflect your interests and pace&mdash;from spiritual pilgrimages in Lumbini to cultural circuits in the Kathmandu Valley, jungle safaris in Chitwan to sunrise views over the Annapurna range'=>'Nous concevons des expériences de voyage qui reflètent vos intérêts et votre rythme&mdash;des pèlerinages spirituels à Lumbini aux circuits culturels dans la vallée de Katmandou, des safaris dans la jungle de Chitwan aux levers de soleil sur la chaîne de l\'Annapurna','We do not sell your data'=>'Nous ne vendons pas vos données','We encourage all clients to:'=>'Nous encourageons tous nos clients à :','We guide you through booking and preparing for your biometrics or in-person appointment, so there are no surprises on the day.'=>'Nous vous accompagnons dans la prise de rendez-vous et la préparation de votre rendez-vous biométrique ou en personne, pour qu\'il n\'y ait aucune surprise le jour J.','We help you pull together what is missing and arrange your file in the order the embassy expects to see it.'=>'Nous vous aidons à rassembler ce qui manque et à organiser votre dossier dans l\'ordre attendu par l\'ambassade.','We implement <strong>secure protocols</strong> to safeguard your personal data.'=>'Nous mettons en place des <strong>protocoles sécurisés</strong> pour protéger vos données personnelles.','We manage the upload or physical submission of your file, whether it goes through an embassy portal or a visa application center.'=>'Nous gérons le téléversement ou le dépôt physique de votre dossier, que ce soit via un portail d\'ambassade ou un centre de demande de visa.','We may collect the following when you interact with our site or services:'=>'Nous pouvons collecter les éléments suivants lorsque vous interagissez avec notre site ou nos services :','We may partner with advertising networks — Facebook or Google Ads, for example — to show relevant ads based on your browsing.'=>'Nous pouvons collaborer avec des réseaux publicitaires — Facebook ou Google Ads, par exemple — afin d\'afficher des publicités pertinentes selon votre navigation.','We may revise this Cookie Policy to reflect changes in <strong>law or technology</strong>. Check back periodically to stay informed.'=>'Nous pouvons réviser cette politique de cookies pour refléter les évolutions <strong>légales ou technologiques</strong>. Consultez-la régulièrement pour rester informé.','We may update this Privacy Policy from time to time. Updates will be <strong>posted on this page</strong>.'=>'Nous pouvons mettre à jour cette politique de confidentialité de temps à autre. Les mises à jour seront <strong>publiées sur cette page</strong>.','We offer a full suite of travel support&mdash;from domestic and international air ticketing, hotel bookings, and vehicle rentals to visa assistance, insurance coordination, and emergency heli-rescue services. We also support outbound travel for Nepali travelers looking to explore international destinations.'=>'Nous offrons une gamme complète de services de voyage&mdash;billetterie aérienne nationale et internationale, réservations d\'hôtel et locations de véhicules, jusqu\'à l\'assistance visa, la coordination d\'assurance et les services d\'hélisecours d\'urgence. Nous accompagnons aussi les voyageurs népalais souhaitant explorer des destinations internationales.','We operate under specific guiding frameworks, including:'=>'Nous opérons selon des cadres de référence précis, notamment :','We organize mindfulness and wellness retreats in serene locations&mdash;like yoga in Pokhara, monastery stays in the hills of Solu, or shamanic healing journeys in western Nepal. Our retreats are ideal for those looking to reconnect with themselves and the natural world.'=>'Nous organisons des retraites de pleine conscience et de bien-être dans des lieux sereins&mdash;yoga à Pokhara, séjours en monastère dans les collines de Solu, ou voyages de guérison chamanique dans l\'ouest du Népal. Nos retraites sont idéales pour ceux qui souhaitent se reconnecter à eux-mêmes et au monde naturel.','We periodically assess performance through <strong>measurable KPIs</strong>.'=>'Nous évaluons régulièrement nos performances via des <strong>indicateurs mesurables</strong>.','We recognise that sustainability is not just an environmental concern — it is an integrated approach involving ethical business practices, community empowerment, cultural respect, and climate-conscious travel. This policy outlines the commitments, values and practices that guide all aspects of our operations and partnerships.'=>'Nous sommes conscients que le développement durable ne se limite pas à une simple question environnementale : il s\'agit d\'une approche globale qui englobe des pratiques commerciales éthiques, l\'autonomisation des communautés, le respect des cultures et des modes de voyage respectueux du climat. La présente politique définit les engagements, les valeurs et les pratiques qui guident tous les aspects de nos activités et de nos partenariats.','We recommend scheduling <strong>buffer days</strong> and securing travel insurance that covers such disruptions.'=>'Nous recommandons de prévoir des <strong>jours tampons</strong> et de souscrire une assurance voyage couvrant ce type de perturbation.','we reply personally'=>'nous répondons personnellement','We reserve the right to make necessary changes to the itinerary, accommodation, or services due to unforeseen circumstances (weather, strikes, availability).'=>'Nous nous réservons le droit d\'apporter les modifications nécessaires à l\'itinéraire, à l\'hébergement ou aux services en raison de circonstances imprévues (météo, grèves, disponibilité).','We serve a wide spectrum of travelers&mdash;adventure seekers, wellness enthusiasts, volunteers, cultural explorers, and first-time visitors&mdash;offering both set itineraries and fully customized journeys across Nepal and beyond. Our approach is grounded in authenticity, sustainability, and human connection.'=>'Nous accueillons un large éventail de voyageurs&mdash;amateurs d\'aventure, passionnés de bien-être, bénévoles, explorateurs culturels et primo-visiteurs&mdash;en proposant à la fois des itinéraires établis et des voyages entièrement personnalisés à travers le Népal et au-delà. Notre approche est fondée sur l\'authenticité, la durabilité et le lien humain.','We use cookies to improve your browsing experience. Cookies help us:'=>'Nous utilisons des cookies pour améliorer votre expérience de navigation. Les cookies nous aident à :','We use your data to:'=>'Nous utilisons vos données pour :','Website'=>'Site web','Wellness & stillness'=>'Bien-être & sérénité','Wellness &amp; Retreats'=>'Bien-être et retraites','What Are Cookies?'=>'Que sont les cookies ?','What cookies are, whose cookies run on our pages, how to manage them, and how this policy changes over time.'=>'Ce que sont les cookies, quels cookies fonctionnent sur nos pages, comment les gérer, et comment cette politique évolue dans le temps.','What grows and what lives here'=>'Ce qui y pousse et ce qui y vit','What is the best time to visit Nepal?'=>'Quelle est la meilleure période pour visiter le Népal ?','What we ask of every traveller'=>'Ce que nous demandons à chaque voyageur','What we collect and why'=>'Ce que nous collectons et pourquoi','What we collect, why we collect it, who it is shared with, how long we keep it, and the rights you have over it.'=>'Ce que nous collectons, pourquoi, avec qui c\'est partagé, combien de temps nous le conservons, et les droits dont vous disposez à ce sujet.','What we offer'=>'Ce que nous proposons','What we serve on trips'=>'Ce que nous servons pendant les voyages','What you can request'=>'Ce que vous pouvez demander','When plans must change'=>'Quand les plans doivent changer','When to come'=>'Quand venir','When you leave a comment on our site'=>'Lorsque vous laissez un commentaire sur notre site','Where it sits'=>'Où il se situe','Where Your Data Is Sent'=>'Où vos données sont envoyées','While no system is completely immune, we strive to maintain the <strong>highest standards</strong> in data protection.'=>'Bien qu\'aucun système ne soit totalement infaillible, nous nous efforçons de maintenir les <strong>normes les plus élevées</strong> en matière de protection des données.','Who lives here'=>'Qui y vit','Who owns this policy'=>'Qui est responsable de cette politique','Who We Are'=>'Qui nous sommes','Who We Share Your Data With'=>'Avec qui nous partageons vos données','Why this policy exists'=>'Pourquoi cette politique existe','Winter (Dec, Jan, Feb)'=>'Hiver (déc., janv., fév.)','Within 15 days, a booking <strong>may be transferred</strong> to a future date or another person, subject to availability.'=>'Dans les 15 jours, une réservation <strong>peut être transférée</strong> à une date ultérieure ou à une autre personne, sous réserve de disponibilité.','Write to our Kathmandu head office, or speak with our worldwide representative closest to you.'=>'Écrivez à notre siège social à Katmandou ou contactez notre représentant international le plus proche de chez vous.','Write to us'=>'Écrivez-nous','Write your message here...'=>'Écrivez votre message ici...','Yes. A trip can combine sightseeing or trekking with several quieter days for meditation, yoga or wellness. This is one of the clearest ways for iFly Nepal\'s travel and retreat services to work together.'=>'Oui. Un voyage peut combiner visites ou trek avec plusieurs jours plus calmes consacrés à la méditation, au yoga ou au bien-être. C\'est l\'une des façons les plus claires de faire fonctionner ensemble les services de voyage et de retraite d\'iFly Nepal.','Yojana, Business Development Lead'=>'Yojana, responsable du développement commercial','You can manage cookie settings through your browser or opt out of certain tracking. See our %s for the full detail.'=>'Vous pouvez gérer les paramètres de cookies via votre navigateur ou refuser certains suivis. Consultez notre %s pour plus de détails.','You can manage or disable cookies in your browser settings:'=>'Vous pouvez gérer ou désactiver les cookies dans les paramètres de votre navigateur :','You must inform us of any <strong>medical conditions, allergies, or dietary restrictions</strong> in advance.'=>'Vous devez nous informer à l\'avance de toute <strong>condition médicale, allergie ou restriction alimentaire</strong>.','You receive a checklist built around your specific visa type and destination, so you know exactly what to gather and in what form.'=>'Vous recevez une liste de vérification adaptée à votre type de visa et à votre destination, afin de savoir exactement quoi rassembler et sous quelle forme.','You should also not become involved with drugs. Being found in possession of even very small quantities of drugs can lead to imprisonment.'=>'Vous ne devez pas non plus vous impliquer avec des drogues. Être trouvé en possession, même de très petites quantités, peut entraîner une peine d\'emprisonnement.','Your data'=>'Vos données','Your data is <strong>never sold or misused</strong>.'=>'Vos données ne sont <strong>jamais vendues ni utilisées à mauvais escient</strong>.','Your email address'=>'Votre adresse e-mail','Your full name'=>'Votre nom complet','Your local point of contact, connected directly with our Nepal-based team. Every number below reaches us on Mobile and WhatsApp.'=>'Votre interlocuteur local, en lien direct avec notre équipe basée au Népal. Tous les numéros ci-dessous vous permettent de nous joindre par téléphone portable et sur WhatsApp.','Your Nepal adventure awaits'=>'Votre aventure au Népal vous attend','Your policy must include <strong>emergency evacuation, medical coverage, and trip cancellation / interruption</strong>.'=>'Votre contrat doit inclure <strong>l\'évacuation d\'urgence, la couverture médicale et l\'annulation ou l\'interruption de voyage</strong>.','Your Question / Message'=>'Votre question / message','Your responsibility before you travel'=>'Vos obligations avant de partir en voyage','Your Rights'=>'Vos droits','Your WhatsApp number'=>'Votre numéro WhatsApp','YouTube'=>'YouTube','© %1$s %2$s. %3$s'=>'© %1$s %2$s. %3$s','— Select a guide —'=>'— Choisissez un guide —']];
